  abortChef(k); abortErrand(k);
  k.duty = false; k.pendingOff = false; k.ksC = KS.idle; k.carrying = null;
  k.dsC = DS.home; k.csC = 0;
  rosterGen++;
  k.p.job = other; k.workBiz = other; k.p.shift = "D"; k.p.employer = null;
  k.fishSpot = null;
