// ---------------------------------------------------------------- sound (from CS1)
// THE PLAYLIST HAS AN ENERGY COLUMN, and two tracks that are not in the
// rotation at all (Matt, 2026-08-21: "energy match the songs though and think
// about if some are event-appropriate").
//
// Twelve tracks used to play in a fixed loop, which meant a lullaby could land
// on the busiest afternoon of the week and a dance number on a dead Sunday
// night. `e` is what a track is FOR - 0 calm, 1 steady, 2 lively - and the
// picker reads the town rather than a counter (see targetEnergy).
//
// `role` takes a track OUT of the rotation because it belongs to a moment:
//   title - the start screen, which is what the track is literally called
//   end   - the ferry ending and the bankruptcy card, both of which are
//           thirty-one seconds of somebody telling you how it went
// A roled track is never picked by the rotation, so it keeps its meaning: a
// win sting that turns up on a Tuesday afternoon is not a win sting.
const PLAYLIST = [
  { src: "music/pixel-wave-waltz.mp3", name: "PIXEL WAVE WALTZ", e: 1 },
  { src: "music/regalia-of-the-surf.mp3", name: "REGALIA OF THE SURF", e: 1 },
  { src: "music/regalia-waltz.mp3", name: "REGALIA WALTZ", e: 1 },
  { src: "music/butter-pow.mp3", name: "BUTTER POW", e: 0 },
  { src: "music/carnival-of-the-glitch.mp3", name: "CARNIVAL OF THE GLITCH", e: 2 },
  { src: "music/pixomatic-moon.mp3", name: "PIXOMATIC MOON", e: 0 },
  { src: "music/dense-portal.mp3", name: "DENSE PORTAL", e: 2 },
  { src: "music/dance-up.mp3", name: "DANCE UP", e: 2 },
  { src: "music/lantern-circuit.mp3", name: "LANTERN CIRCUIT", e: 1 },
  { src: "music/marble-rain.mp3", name: "MARBLE RAIN", e: 0 },
  { src: "music/rain-circuit-lullaby.mp3", name: "RAIN CIRCUIT LULLABY", e: 0 },
  { src: "music/goat-circuit.mp3", name: "GOAT CIRCUIT", e: 1 },
  // ---- DENSE DANCE + CLONKBOY (2026-08-21). Energy read off what each track
  // actually is: the lullabies and the porch-sitting ones carry the night, the
  // thumping ones carry a full house.
  { src: "music/grease-man.mp3", name: "GREASE MAN", e: 0 },
  { src: "music/frog-ledger.mp3", name: "FROG LEDGER", e: 0 },
  { src: "music/front-porch.mp3", name: "FRONT PORCH", e: 0 },
  { src: "music/island-sand.mp3", name: "ISLAND SAND", e: 1 },
  { src: "music/raster-beach.mp3", name: "RASTER BEACH", e: 1 },
  { src: "music/train-whistle.mp3", name: "TRAIN WHISTLE", e: 1 },
  { src: "music/peenball.mp3", name: "PEENBALL", e: 2 },
  { src: "music/power-limbo.mp3", name: "POWER LIMBO", e: 2 },
  { src: "music/beach-volleyball-start-screen.mp3", name: "BEACH VOLLEYBALL", e: 1, role: "title" },
  { src: "music/you-win-game-over.mp3", name: "YOU WIN/GAME OVER", e: 1, role: "end" },
];
// WHAT THE TOWN IS DOING, as one number the picker can match a track to.
// Deliberately read off things a player can SEE - the clock, the light, and how
// many people are on the promenade - so the music agreeing with the town is
// something you notice rather than something you are told.
function targetEnergy() {
  if (typeof darkness === "function" && darkness() > 0.6) return 0;   // after dark: the town is asleep
  if (typeof townOpen === "function" && !townOpen()) return 0;        // before the shutters go up
  const crowd = (typeof customers !== "undefined" ? customers : []).filter(k => k && !k.gone).length;
  return crowd >= 6 ? 2 : crowd >= 2 ? 1 : 0;
}
// ...and the track for it. Never a roled track, never the one just played, and
// it falls back through the neighbouring energies rather than going silent -
// a town with no lively track left still gets music, just calmer music.
function pickTrack() {
  const want = targetEnergy();
  for (const d of [0, 1, 2, 3]) {
    const pool = [];
    for (let i = 0; i < PLAYLIST.length; i++) {
      const t = PLAYLIST[i];
      if (t.role || i === trackIdx) continue;
      if (Math.abs((t.e == null ? 1 : t.e) - want) === d) pool.push(i);
    }
    if (pool.length) return pool[(vrand() * pool.length) | 0];   // music is view: the shuffle never advances the sim stream
  }
  return trackIdx;
}
function roleTrack(role) {
  for (let i = 0; i < PLAYLIST.length; i++) if (PLAYLIST[i].role === role) return i;
  return -1;
}
let musicOn = false, music = null, muted = false;   // opt-IN for new players (SFX stays on)
let musNudges = 0, musNudged = false;               // invite, don't nag: gives up after 3 sessions
function toggleMute() {
  muted = !muted;
  if (muted) { if (music) music.pause(); }
  else if (musicOn) { if (music) music.play().catch(() => {}); else startMusic(); }
}
let trackIdx = (srand() * PLAYLIST.length) | 0;
function playTrack(i) {
  if (music) { music.pause(); music = null; }
  trackIdx = ((i % PLAYLIST.length) + PLAYLIST.length) % PLAYLIST.length;
  const t = PLAYLIST[trackIdx];
  music = new Audio(t.src);
  music.volume = 0.55;
  // WHAT FOLLOWS A TRACK IS CHOSEN, NOT COUNTED. The next one is picked to
  // match what the town is doing when this one runs out - see pickTrack.
  music.addEventListener("ended", () => { music = null; if (musicOn) playTrack(pickTrack()); });
  music.play().then(() => { if (!toast) toast = { text: "NOW PLAYING: " + t.name, t: 4 }; })   // don't stomp a live toast (e.g. the migration refund)
    .catch(() => { music = null; });
}
function startMusic() { if (!music && musicOn && !muted) playTrack(pickTrack()); }
// THE TWO MOMENTS THAT OWN THEIR OWN MUSIC. Called from the screens that mean
// them; each one only interrupts if it is not already the thing playing, so a
// 31-second sting is not restarted every frame of the ending it belongs to.
function playRole(role) {
  const i = roleTrack(role);
  if (i < 0 || !musicOn || muted) return;
  if (music && trackIdx === i) return;
  playTrack(i);
}
function toggleMusic() {
  musicOn = !musicOn;
  if (!musicOn && music) { music.pause(); music = null; } else if (musicOn) startMusic();
}
let AC = null;
function beep(freq, dur, type, vol, when) {
  if (!soundOn || muted) return;
  // A SCIENCE RUN IS SILENT. The lab's loop lives thirty days in one blocked
  // task, and the audio clock barely moves while it does - so every till chime
  // of the month lands on the same AC.currentTime and discharges as one blast
  // when the loop yields. Dropped, not deferred: the month happened, the
  // sounds didn't. (SCI.run also covers the scrub shuttles, whose loads pop
  // the same way.) The completion ding fires after run clears - it survives.
  if (SCI.run) return;
  window._beeps = (window._beeps || 0) + 1;   // the probe's counter: scheduled, not dropped
  if (!AC) try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return; }
  const t = AC.currentTime + (when || 0);
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = type || "square"; o.frequency.value = freq;
  g.gain.setValueAtTime(vol || 0.04, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t + dur);
}
const sfx = {
  coin: () => { beep(880, .08); beep(1320, .12, "square", .04, .07); },
  buy: () => { beep(520, .06); beep(700, .08, "square", .04, .05); },
  angry: () => { beep(220, .15, "sawtooth", .03); beep(160, .2, "sawtooth", .03, .12); },
  ding: () => beep(1560, .1, "triangle", .05),
  bus: () => beep(300, .2, "triangle", .04),
  // ambient color, kept very quiet
  gull: () => { beep(1760, .12, "triangle", .02); beep(1320, .16, "triangle", .018, .12); },
  splash: () => { beep(520, .05, "sine", .03); beep(300, .09, "sine", .025, .05); },
};

// ---------------------------------------------------------------- economy
function fmt(c) {   // cents in, whole dollars out - every caller is money
  let n = $d(c);
  if (n >= 1e6) return (n / 1e6).toFixed(1) + "M";
  if (n >= 1e4) return (n / 1e3).toFixed(1) + "K";
  return String(n);
}
function popText(txt, x, y, color) {
  floaters.push({ x, y, t: 1.6, text: txt, color: color || [255, 255, 255] });
}
// cents state, dollar glass: the ONE display divisor
function $d(c) { return Math.round(c / 100); }
function earn(amt, x, y) {
  coins += amt; lifetime += amt;
  earnHist.push({ t: T, amt });
  popText("+$" + $d(amt), x, y, [255, 230, 120]);
  sfx.coin();
}
function expense(amt, x, y, label) {
  coins -= amt;
  earnHist.push({ t: T, amt: -amt });   // income rate is net
  popText("-$" + $d(amt) + (label ? " " + label : ""), x, y, [255, 120, 120]);
}
function incomeRate() {
  while (earnHist.length && earnHist[0].t < T - 60 * TICK_HZ) earnHist.shift();
  if (!earnHist.length) return 0;
  return earnHist.reduce((s, e) => s + e.amt, 0) / Math.max(10, (T - earnHist[0].t) / TICK_HZ);
}

// ---------------------------------------------------------------- save
// N SLOTS, not one key. Every slot holds the SAME envelope save() has always
// written - treated here as an OPAQUE blob so other systems can keep adding
// fields to it - plus two sidecar keys this layer owns:
//   _ver   the format guard an import is checked against
//   _meta  the at-a-glance card (day, till, rep, pop, crew roster) the SAVED
//          TOWNS screen renders without loading anything
// _meta is always derivable from the envelope alone (slotMeta), so migrated and
// imported saves get one for free and a stale one can never lie.
const SAVE_KEY = "crabshack3_v1";        // the legacy single-slot key: migration source only
// 2 = the cents era (numeric slice 1). A cents save read by a pre-cents build
// would inflate every balance a hundredfold; that build's own "FROM A NEWER
// CRAB SHACK" gate is exactly the refusal needed, so the bump IS the guard.
const SAVE_VER = 4;   // 4: personas may carry dm/dr (dream-replay rung 0); a ver-3 save is the zero delta
const SLOTS = 5;
const ACTIVE_KEY = SAVE_KEY + "_active";
function slotKey(i) { return SAVE_KEY + "_s" + i; }
function nowMs() { try { return Date.now(); } catch (e) { return 0; } }   // headless sandboxes may not have a clock
let activeSlot = 1;                      // autosave goes here; persisted in ACTIVE_KEY
// OWNERSHIP, because the autosave writes whatever town is IN MEMORY, and the
// town in memory is not always the slot's town. Proven the hard way, twice in
// one browser session: opening `?lab` and closing the tab buried a day-4 save
// under the lab's fresh day-1 town, and a save the loader REJECTED (one bad
// field - everything else recoverable) was buried the same way by the fresh
// town born from its own failure. So the session must EARN the slot before
// save() will write it: loading from the slot earns it, booting onto an EMPTY
// slot earns it (a first town must still autosave), and the player's own
// deliberate acts earn it (starting a new game, PLAY THIS DAY). A lab session
// never earns it by itself, and neither does a town born from a rejected
// envelope - those write nothing, however the tab closes.
let slotOwned = false;
// ============================================================== THE RNG SEAM
// CS3.5 numeric-core slice 0: every sim draw goes through this ONE function -
// the same stream, the same order, byte-identical to calling Math.random()
// directly (the harness seeds the context's Math, which this delegates to).
// It exists so slice 5 can split browser-only draws to a view stream without
// hunting 93 call sites twice, and so a future backend can inject its own
// integer generator at exactly one door.
//
// SLICE 5 lands that split. srand() is still the sim's only door, but the
// door now has a swappable tap: the title screen re-enters real sim code
// (updateBus, maybeQuip, the attract wander) as view-side theatre, and for
// the length of that block the tap points at the VIEW stream below - so the
// SIM stream's draw order is a closed sequence that browser-only theatre can
// never advance. Headless never runs the title, so headless is byte-identical
// by construction; that is the slice's gate, and the draw-count pin scenario
// is its standing tripwire. One deliberate exception, part of the frozen
// stream's spec: trackIdx's load-time draw below DOES execute headless and
// stays on the sim stream - moving it would shift every draw after it.
function srand() { return _rtap ? _rtap() : Math.random(); }   // var + fallback: module-eval draws (trackIdx) fire before initializers run
var _rtap = null;   // null = the default sim stream (the context's Math.random, harness-seeded)
