  if (cust.recipe) {
    if (cust.recipe.id === "taco") tradeImport("corn", 1);          // tortilla-to-be (T3 pilot)
    if (cust.biz === "arcade") tradeImport("power", 1);             // a machine hour
  }
  creditAccomplishment(c, cust);
