    if (cust.need === "food") cust.crab.p.hunger = 0;
    if (cust.need === "drink") {
      cust.crab.quip = { text: ["AHH, THE GOOD STUFF", "QUENCHED!", "COLD AND SWEET"][(srand() * 3) | 0], t: 2.4 * SEC };
      if (window._stats) window._stats.crabDrinks = (window._stats.crabDrinks || 0) + 1;
    }
