    rect(ctx, bx + 8, by - 3, 2, 3, night ? [40, 30, 40] : [90, 70, 70]);
    px(ctx, bx + 8, by - 4, night ? [60, 62, 80] : [200, 205, 214]);   // a smudge of smoke
    if (night) px(ctx, bx + 3, by - 2, [255, 206, 120]);
