// The card is the full readable width of the screen and sits ABOVE the panel in
// both canvas heights (the world always keeps rows 0..PANEL_Y - see the
// geometry block), so one rect table serves the phone and the desktop.
// Where the second column of a KEY row starts. Measured against the widest key
// label the card carries, and hoisted out of the draw so the suite can check
// every label against the same number rather than a copy of it - a scenario
// that asserts its own constant is asserting nothing.
const HELP_KEYCOL = 56;
// THE ROSTER HINT, hoisted out of the draw for the same reason. All three of
// these are FIXED COPY and all three of them used to be over budget - the
// widest ran 187px into the 166 between the card's left margin and its DONE
// chip, so every one of them printed as a sentence ending in "..". fitSmall
// stops a line running off a card; it does not stop it reading as unfinished.
//
// The fix is to WRITE to the budget rather than trim to it, and the only way to
// keep that true is to let the suite measure the same strings the card prints -
// a scenario carrying its own copy of the copy would prove nothing.
function rosterHintBudget(R) { return R.done.x - (R.x + 6) - 6; }
function rosterHint(key, deals) {
  if (deals) return deals + " ON PRIVATE DEALS - ALL RESETS TO $" + $d(bizWage(key));
  return BIZ[key].autoLabor ? "THE ROTA MANAGES ITSELF: SICK DAYS AND OT"
    : "TAP A ROW: SHIFT, OT, SICK OR THE WAGE";
}
function helpRects() {
  const x = 6, y = 6, w = W - 12, h = PANEL_Y - 14;
  const fy = y + h - 13;
  return { x, y, w, h,
    prev: { x: x + 5, y: fy, w: 26, h: 10 },
    next: { x: x + 34, y: fy, w: 26, h: 10 },
    done: { x: x + w - 35, y: fy, w: 30, h: 10 } };
}
function helpFlip(d) {
  helpPage = (helpPage + d + HELP_PAGES.length) % HELP_PAGES.length;
  sfx.ding();
}
// ONE DOOR OUT, and every close goes through it - DONE, a tap off the card and
// Escape alike.
//
// AND IT DOES NOT STOP THE CLOCK, which was the tempting mistake and is against
// the spirit of the game (owner, 2026-08-20, removing the pause chip outright):
// the day running while you read the instructions IS the game. The rule this
// whole pass is written to is narrower than "reading should be free" - a player
// who cannot tell WHAT A BUTTON DOES is a bug; a player losing money while they
// work it out is the design. So the card explains and gets out of the way; it
// buys nobody a single minute.
function closeHelp() {
  if (!helpView) return;
  helpView = false;
  sfx.ding();
}
function toggleHelp() {
  if (helpView) { closeHelp(); return; }
  helpView = true;
  // ...and remember that it has been read, so the chip stops pulsing. Only
  // from PLAY: save() writes the active slot, and writing one from the title
  // screen would mint a phantom town on the shelf for somebody who has done
  // nothing but read the instructions.
  helpSeen = true; helpNudged = true;
  if (screen === "play") save();
  sfx.ding();
}
function drawHelp() {
  if (!helpView) return;
  const R = helpRects(), { x, y } = R, w2 = R.w, h2 = R.h;
  ctx.fillStyle = "rgba(16,12,30,0.72)";
  ctx.fillRect(0, 0, W, H);
  rect(ctx, x - 2, y - 2, w2 + 4, h2 + 4, [30, 20, 36]);
  rect(ctx, x, y, w2, h2, [255, 250, 235]);
  rect(ctx, x, y, w2, 14, [58, 42, 38]);
  const P = HELP_PAGES[helpPage] || HELP_PAGES[0];
  text(ctx, "HOW TO PLAY", x + 6, y + 4, [255, 240, 210]);
  {  // the page's own name, right-aligned in the header bar it shares
    const t2 = P.title;
    smallText(ctx, t2, x + w2 - smallTextWidth(t2) - 6, y + 5, [190, 140, 80]);
  }
  // ONE PITCH FOR EVERY ROW. A blank row is a row, not a special case, which is
  // what keeps a page from silently sliding under its own footer when a line is
  // added - and the footer is where the sweep would catch it if it did.
  let ly = y + 19;
  for (const L of P.lines) {
    if (L[0] === "-") { ly += 4; continue; }
    if (L[0] === "h") smallText(ctx, L[1], x + 8, ly, [180, 90, 40]);
    else if (L[0] === "k") {
      smallText(ctx, L[1], x + 8, ly, [40, 30, 40]);
      smallText(ctx, fitSmall(L[2], w2 - 16 - HELP_KEYCOL), x + 8 + HELP_KEYCOL, ly, [90, 80, 90]);
    } else smallText(ctx, fitSmall(L[1], w2 - 16), x + 8, ly, [70, 62, 72]);
    ly += 8;
  }
  const chip = (r, label, dim) => {
    rect(ctx, r.x, r.y, r.w, r.h, [30, 20, 36]);
    rect(ctx, r.x + 1, r.y + 1, r.w - 2, r.h - 2, dim ? [222, 212, 196] : [190, 140, 80]);
    smallText(ctx, label, r.x + ((r.w - smallTextWidth(label)) >> 1), r.y + 3, [40, 24, 16]);
  };
  chip(R.prev, "<", false);
  chip(R.next, ">", false);
  chip(R.done, "DONE", false);
  const pTxt = (helpPage + 1) + " / " + HELP_PAGES.length;
  smallText(ctx, pTxt, R.next.x + R.next.w + 8, R.next.y + 3, [140, 130, 130]);
}
function tapHelp(p) {
  if (!helpView) return false;
  const R = helpRects();
  const hit = (r) => p.x >= r.x && p.x < r.x + r.w && p.y >= r.y && p.y < r.y + r.h;
  if (hit(R.prev)) { helpFlip(-1); return true; }
  if (hit(R.next)) { helpFlip(1); return true; }
  if (hit(R.done)) { closeHelp(); return true; }
  // ANYWHERE ELSE ON THE CARD TURNS THE PAGE FORWARD, and anywhere off it
  // closes: the same two gestures the day report and the dossier already use,
  // so nothing here has to be learned either.
  const onCard = p.x >= R.x - 2 && p.x < R.x + R.w + 2 && p.y >= R.y - 2 && p.y < R.y + R.h + 2;
  if (onCard) helpFlip(1); else closeHelp();
  return true;
}

// ===========================================================================
// THE SHOP TOOLTIP - see UP_HELP for what it is allowed to say
// ===========================================================================
// WHERE IT GOES, and this was the whole difficulty. The shop grid is two rows
// of buttons that end at y237 of a 240-row canvas, so there is no room under
// it; the nav strip owns PANEL_Y-7..PANEL_Y and its chip row the eleven rows
// above that; and the top of the screen belongs to the character card whenever
// anybody is selected. What is left is the band directly above the MANAGE /
// TOWN chips, which is sky - so the card hangs off the bottom of the world,
// pointing down at the grid it describes.
const SHOPTIP_H = 36;
function shopTipRect() {
  const cy = NAV_MAP.y - NAV_CHIP_H - 1;      // the chip row's own top (see navRects)
  return { x: 2, y: cy - 1 - SHOPTIP_H, w: W - 4, h: SHOPTIP_H };
}
// `probe` is the hover test, which has to answer BEFORE a key is picked; the
// draw asks the same question with a key already in hand.
function shopTipLive(probe) {
  return (probe || !!shopTip) && tab === "shop" && screen === "play" && !gameOver && !helpView
    && !(dossier || manage || boardView || saveView || reportT > 0 || departT > 0)
    && !hireCardLive()   // buying a crab REPLACES the tooltip with the crab: one voice at a time
    && !(window.MergeMode && MergeMode.active());
}
function drawShopTip() {
  if (!shopTipLive()) return;
  const u = UPS[shopTip];
  if (!u) return;
  const R = shopTipRect(), { x, y } = R, w2 = R.w;
  const maxed = u.lvl >= u.max, cost = upCost(u), afford = coins >= cost;
  rect(ctx, x, y, w2, R.h, [30, 20, 36]);
  rect(ctx, x + 1, y + 1, w2 - 2, R.h - 2, [255, 250, 235]);
  // the name, and the price it is asking, at opposite ends of the same line
  text(ctx, u.name, x + 5, y + 4, [58, 42, 38]);
  const cTxt = maxed ? "MAXED OUT" : "$" + fmt(cost);
  text(ctx, cTxt, x + w2 - 5 - textWidth(cTxt), y + 4,
    maxed ? [140, 130, 130] : afford ? [40, 130, 70] : [190, 80, 80]);
  const body = UP_HELP[shopTip] || ["", ""];
  smallText(ctx, fitSmall(body[0] || "", w2 - 10), x + 5, y + 13, [70, 62, 72]);
  smallText(ctx, fitSmall(body[1] || "", w2 - 10), x + 5, y + 20, [70, 62, 72]);
  // the bottom line is the CONSEQUENCE line: what changes about the town on the
  // left, what it costs you every night after on the right. Both derived.
  const eff = maxed ? "NOTHING LEFT TO BUY HERE" : upEffect(shopTip);
  smallText(ctx, eff, x + 5, y + 28, maxed ? [140, 130, 130] : [40, 130, 70]);
  const ong = maxed ? "" : !afford ? "YOU HAVE $" + fmt(Math.floor(coins)) : upOngoing(shopTip);
  if (ong) smallText(ctx, fitSmall(ong, w2 - 14 - smallTextWidth(eff)),
    x + w2 - 5 - smallTextWidth(fitSmall(ong, w2 - 14 - smallTextWidth(eff))), y + 28,
    !afford ? [190, 80, 80] : [150, 110, 40]);
}

// ===========================================================================
// THE HIRE CARD - somebody actually arrives
// ===========================================================================
// The counterpart to hireCrew's camera move and pointer. This says the three
// things a roster entry does not: WHO they are and how they got here, WHAT
// they will do all day, and WHAT THEY COST YOU - a shift window, a wage on
// tonight's bill, and a cot at the shelter, because a hire starts homeless
// like everybody else in this town and nothing anywhere said so.
// ...and what the job IS, per shop, because "COOKS AND SERVES" is a lie about
// an arcade floor. Keyed on the BUSINESS, so a new lot adds a row here and
// nothing else changes - the same shape the policy tables use.
const HIRE_DUTY = { shack: "COOKS AND SERVES AT", juicebar: "POURS AND SERVES AT",
  arcade: "MINDS THE FLOOR AT" };
const HIRE_CARD = { w: 210, h: 62 };
// y78 is measured, not chosen: the character card owns y2..60 (and followCrab
// has just put the new hire on it), the toast band is y62..75, and the nav
// chip row starts at y157. This is the hole between them.
function hireCardRect() { return { x: ((W - HIRE_CARD.w) / 2) | 0, y: 78, w: HIRE_CARD.w, h: HIRE_CARD.h }; }
function hireCardLive() {
  return !!(hireCard && hireCard.t > 0 && hireCard.c && screen === "play" && !gameOver && !helpView
    && !(dossier || manage || boardView || saveView || reportT > 0 || departT > 0));
}
function drawHireCard() {
  if (!hireCardLive()) return;
  const c = hireCard.c, p = c.p, R = hireCardRect(), { x, y } = R;
  rect(ctx, x - 2, y - 2, R.w + 4, R.h + 4, [30, 20, 36]);
  rect(ctx, x, y, R.w, R.h, [255, 250, 235]);
  rect(ctx, x, y, R.w, 12, [40, 130, 70]);
  text(ctx, p.name + " JOINS THE CREW", x + 6, y + 3, [235, 255, 240]);
  // the portrait, at 2x, in their own shell colours - the same face the crew
  // card and the dossier draw, so "which one is that" has one answer
  blit(ctx, art2("c" + p.color, CRAB_ARTS[p.color].a), x + 6, y + 16);
  const acc = ACCESSORIES[p.acc];
  if (acc) blit(ctx, art2("a" + p.acc, acc.art), x + 6 + acc.dx * 2, y + 16 + acc.dy * 2);
  const tx = x + 40;
  smallText(ctx, fitSmall(hireCard.how || "", R.w - 46), tx, y + 16, [110, 100, 110]);
  const b = BIZ[p.job] || BIZ.shack;
  smallText(ctx, fitSmall((HIRE_DUTY[p.job] || "WORKS AT") + " " + b.name, R.w - 46), tx, y + 25, [70, 62, 72]);
  const win = baseShift(c);   // their own contracted hours, whatever shop and shift they landed on
  smallText(ctx, (p.shift === "M" ? "MORNINGS " : p.shift === "E" ? "EVENINGS " : "DAYS ") + win.label,
    tx, y + 34, [70, 90, 130]);
  smallText(ctx, "$" + $d(wageRate(c)) + " A SHIFT, ON TONIGHT'S BILL AT 20:00", tx, y + 43, [190, 80, 80]);
  smallText(ctx, p.homeless ? "SLEEPS AT THE SHELTER UNTIL THEY CAN AFFORD A ROOM"
    : "HAS SOMEWHERE TO SLEEP", x + 6, y + 53, [110, 100, 110]);
}
// ...and the pointer in the world, so the card and the town agree about who is
// being talked about. Drawn in the world pass, over the crab's head, bobbing.
function drawHirePointer() {
  if (!hireCardLive()) return;
  const c = hireCard.c;
  if (c.hidden || c.x == null) return;
  const sx = Math.round(c.x + 8 - camX);
  if (sx < 4 || sx > W - 4) return;
  // 20 above the feet, not 26: the arrow is 9 rows tall (a 4-row stem over a
  // 5-row head) and at 26 its stem printed behind the bottom edge of the hire
  // card, which sits at y140. This lands it in the gap between the card and the
  // crab's own head, which is what it is pointing at.
  const bob = Math.round(Math.sin(viewT * 6) * 2);
  const py = Math.round(c.y) - 20 + bob;
  for (let i = 0; i < 5; i++) rect(ctx, sx - (4 - i), py + i, 2 * (4 - i) + 1, 1, [96, 232, 120]);
  rect(ctx, sx - 1, py - 4, 3, 4, [96, 232, 120]);
}

// ---------------------------------------------------------------- main loop
let last = performance.now(), saveT = 0, msAcc = 0;
// ---------------------------------------------------------------- THE SEAM
// The sim/view split (perf-ladder rung 1). State flows ONE WAY, sim -> view:
// simClock and simTown are the whole of the world's advance - everything the
// headless fingerprint sees, announcement state included (toasts, floaters,
// the report and departure cards - the suite drives and reads them, so they
// are observable sim, not decoration). viewFrame and the intro/title screens
// are READERS: they may look at anything and write nothing the sim reads.
// A headless run never enters a view function BY CONSTRUCTION - the one gate
// in frame() is the only crossing, and window._viewCalls counts crossings so
// the suite can assert zero. The two "go and look at this" camera snaps
// (hireCrew, the ferry ending) are one-way EMISSIONS into view state, and the
// title screen's attract-mode wander is view-side sim theatre - browser-only
// by construction, srand-inventoried for slice 5.
function simClock(dt, rawMs) {
  if (hireCard) { hireCard.t -= rawMs / 1000; if (hireCard.t <= 0) hireCard = null; }   // WALL seconds, deliberately
  if (saveConfirmT > 0) { saveConfirmT -= dt; if (saveConfirmT <= 0) saveConfirm = null; }
  if (saleArmT > 0) { saleArmT -= dt; if (saleArmT <= 0) saleArm = null; }
  if (sendArmT > 0) { sendArmT -= dt; if (sendArmT <= 0) sendArm = false; }
  if (sendArm && !sendShown()) { sendArm = false; sendArmT = 0; }   // selection changed under the arm
  if (upArmT > 0) { upArmT -= dt; if (upArmT <= 0) upArm = null; }   // the accommodation chips' arm
  if (ferryArm > 0) ferryArm -= dt;
  if (won) winT += dt;   // the beat before the ending card: she comes alongside first
  if (askArmT > 0) { askArmT -= dt; if (askArmT <= 0) askArm = null; }
  if (saveMsg && saveMsg.t > 0) { saveMsg.t -= dt; if (saveMsg.t <= 0) saveMsg = null; }
  if (!gameOver && screen === "play") tday += dtT;
  reclock();
  if (tday >= DAY_TICKS) {
    tday -= DAY_TICKS; reclock(); day++;
    // THE WORLD-EVENT POINT (phase D): the day roll is the one world event
    // every civics calendar counts from. Fired before the day's books reset
    // so a hook reads yesterday's rep/coins, exactly what a calendar phase
    // would settle against.
    if (HOOKS.worldEvent.length) fireHooks("worldEvent", { kind: "dayRoll", day, rep, coins });
    mistRoll();   // tonight's shore, drawn once and held as an integer
    dayOpen = coins;   // the mark the panel's TODAY readout is measured from
    settleFishMarket();   // the day's landings vs the day's appetite set tomorrow's pier price
    townCatch = Math.min(townCatch, 4); rep = rep + idiv((30000 - rep) * 6, 100);   // nightly relaxation, exact; floor's deadband at milli is 0.017 rep
    for (const c of allCrabs()) { c.workedToday = false; c.otMin = 0; }   // a new day's ledger
    trade.day = { fish: 0, corn: 0, water: 0, power: 0, fruit: 0, paper: 0 }; trade.landedDay = 0;
    townFund.dayIn = 0; townFund.dayOut = 0; townFund.youPaid = 0; townFund.youGot = 0;   // the fund's own day book
    today = newDayLog(); today.repStart = rep;
  }
  if (ffSleep && (gameOver || screen !== "play" || (day >= ffSleepDay && tmin >= 6.5 * 60 && tmin < 12 * 60)))
    ffSleep = false;   // morning - or anything that should break the spell
  if (screen === "play" && tmin >= 20 * 60 && lastRentDay !== day) {
    today.repEnd = rep;
    lastRentDay = day;
    for (const c of crabs) c.p.walletPrev = c.p.wallet;
    (window.dayLog = window.dayLog || []).push({ day, close: Math.round(coins) });
    // 1. wages: pay every crab you can afford
    //
    // THE RENT IS RESERVED BEFORE A PENNY OF PAYROLL GOES OUT, and that one
    // line is what makes missing salary an ALTERNATIVE to bankruptcy rather
    // than a step on the way to it. Before it, the wage loop spent the till
    // down to nothing and the landlord's bill hit an empty drawer - so paying
    // your crew was itself a way to get evicted, and the player never got the
    // choice because the money was already gone.
    //
    // Now the cliff and the soft debt are ranked the way the world ranks them:
    // the landlord evicts you, so he is paid first; the crew can only quit, so
    // they are paid out of what is left and carry the rest as back pay. On any
    // ordinary night the till clears both and this reserve does nothing at all.
    const rentReserve = Math.max(0, Math.round(totalRent()));
    let wages = 0, backPaid = 0, missedPay = 0, missedN = 0;
    // BACK PAY COMES FIRST, and it comes before tonight's wages on purpose: a
    // crab who was stiffed on Tuesday and the till recovers on Wednesday is
    // owed Tuesday, not given a fresh start. It also means the debt clears
    // itself the moment the town can afford it - a player who missed the
    // report card has not lost the ability to put it right, only the choice
    // about WHEN.
    for (const c of crabs) {
      c._stiffed = false;
      const owed = Math.max(0, Math.round(c.p.owed || 0));
      if (owed <= 0 || coins - rentReserve < owed) continue;
      coins -= owed; c.p.wallet += owed; c.p.owed = 0;
      wages += owed; backPaid += owed;
      c.p.gripe = Math.max(0, (c.p.gripe || 0) - WAGE_CFG.MISSED * 2);
      if (c.p.walkoutWhy === "pay") { c.p.walkout = null; c.p.walkoutWhy = null; }
      crabLog(c, "money", "GOT $" + $d(owed) + " IN BACK PAY", 0);   // DIARY
      popText("BACK PAY!", c.x - 10, FLOOR_Y - 40, [140, 255, 160]);
      today.moved.push(c.p.name + " WAS PAID $" + $d(owed) + " IN BACK PAY");
    }
    for (const c of crabs) {
      if (c.p.sick && !c.workedToday) continue;      // sick day: no work, no pay (a REQUIRED crab who worked is paid in full)
      // day off OR a walk-out: same rule - the bill dips, the wallet doesn't.
      // The walk-out is the one that stings, because nobody covered it either.
      if (awayToday(c) && !c.workedToday) continue;
      const prem = Math.round(otPayToday(c));        // overtime premium on top of the flat day
      const due = Math.round(basePayToday(c)) + prem;   // the day, priced by the hours contracted
      if (coins - rentReserve >= due) {
        coins -= due; c.p.wallet += due; wages += due;
        crabLog(c, "money", "DREW $" + $d(due) + " IN WAGES", 0);   // DIARY
        if (prem > 0) {
          popText("OT +$" + $d(prem), c.x - 4, FLOOR_Y - 40, [255, 216, 96]);
          if (window._stats) {
            window._stats.otPay = (window._stats.otPay || 0) + prem;
            window._stats.otMin = (window._stats.otMin || 0) + Math.round(c.otMin || 0);
          }
        }
      } else {
        // NOT PAID IS NOT FORGIVEN. It is a debt the town carries, a grievance
        // that will not shed tonight, and - on the report card that is about to
        // come up - an offer to borrow the difference.
        c.p.owed = Math.max(0, Math.round(c.p.owed || 0)) + due;
        c._stiffed = true;
        missedPay += due; missedN++;
        crabLog(c, "peril", "WENT UNPAID - $" + $d(due) + " OWED", 0);   // DIARY
        popText("NO PAY?!", c.x, FLOOR_Y - 30, [255, 120, 120]);
      }
    }
    if (missedN > 0) {
      today.moved.push("PAYDAY MISSED - $" + fmt(missedPay) + " OWED TO "
        + missedN + " CRAB" + (missedN === 1 ? "" : "S"));
      if (typeof sfx !== "undefined" && sfx.angry) sfx.angry();
      if (window._stats) {
        window._stats.paydayMissed = (window._stats.paydayMissed || 0) + 1;
        window._stats.wagesOwed = (window._stats.wagesOwed || 0) + missedPay;
      }
    }
    if (wages > 0) earnHist.push({ t: viewT, amt: -wages });
    // 2. house rent from each crab's own wallet; broke crabs move to the shelter
    let evictedNames = [];
    for (const c of allCrabs()) {
      logNightly(c);   // DIARY: the nights tally, the day's catch as one line, and what they took to bed
      c.p.thirst = Math.min(Q20, (c.p.thirst || 0) + Math.floor(qn(0.15) * ((c.p.tired || 0) > qn(0.5) ? 1.5 : 1)));   // a dry night - drier after a hard day
      if (c.workedToday) { c.p.tired = Math.min(Q20, (c.p.tired || 0) + bodyOf(c).T.night); c.workedToday = false; }   // the day's work catches up at dusk; idlers owe nothing
      if (c.p.homeless) {
        // shelter is free; move into a free house once savings allow
        const used = new Set(allCrabs().filter(k => !k.p.homeless).map(k => k.p.house));
        // nobody rents the far end of town from their own job: take the free
        // lot CLOSEST to where you work. (Fishers were buying the promenade -
        // 1400px from the pier - then spending the week commuting, earning
        // nothing, and losing the house again. The beach cottages exist.)
        let free = -1, bestD = Infinity;
        const door = jobDoor(c);
        for (let h = 0; h < HOUSE_XS.length; h++) {
          if (used.has(h)) continue;
          const d = Math.abs(HOUSE_XS[h] - door);
          if (d < bestD) { bestD = d; free = h; }
        }
        if (free >= 0 && c.p.wallet >= MOVE_IN_COST + HOUSE_RENT) {
          c.p.wallet -= MOVE_IN_COST; c.p.house = free; c.p.homeless = false;
          logHome(c, "MOVED INTO " + placeName(c.p) + " - $" + $d(MOVE_IN_COST));   // DIARY
          today.moved.push(c.p.name + " GOT A HOUSE");
          toast = { text: c.p.name + " MOVED INTO A HOUSE!", t: 5 };
          popText("HOME SWEET HOME", HOUSE_XS[free] + 8, 100, [140, 255, 160]);
          sfx.ding();
        }
      } else if (c.p.boat != null) {
        // live-aboard: no landlord, just the harbormaster's mooring fee
        // (a boat is owned outright - a broke night runs a tab, never an eviction)
        if (c.p.wallet >= MOORING_FEE) c.p.wallet -= MOORING_FEE;
      } else if (c.p.fisher && freeBerth() >= 0 && c.p.wallet >= BOAT_COST + MOORING_FEE) {
        // top of the ladder: a housed fisher with deep savings trades up to a
        // live-aboard boat; the old house frees for the next climber
        const berth = freeBerth();
        c.p.wallet -= BOAT_COST;
        c.p.boat = berth; c.p.house = null;
        logHome(c, "MOVED ABOARD THE " + BOAT_NAMES[berth] + " - $" + $d(BOAT_COST));   // DIARY
        c.fishSpot = boatSpot(berth);
        today.moved.push(c.p.name + " MOVED ABOARD THE " + BOAT_NAMES[berth]);
        toast = { text: c.p.name + " MOVED ABOARD!", t: 6 };
        popText("LIVE-ABOARD!", BOAT_BERTHS[berth].x + 2, 58, [140, 220, 255]);
        sfx.ding();
      } else if (c.p.wallet >= HOUSE_RENT) {
        // A CUT OF THE RENTS, if that is the purse the town voted for. It comes
        // out of this payment on its way past, so the tenant pays their same $10
        // either way - the town negotiated with Mr. Pincherton over HIS book, and
        // what the fund does not take is destroyed exactly as it always was.
        const cut = rentCut(c, HOUSE_RENT);
        c.p.wallet -= HOUSE_RENT - cut;
        crabLog(c, "money", "PAID $" + $d(HOUSE_RENT) + " HOUSE RENT", 600);   // DIARY: once a night, never twice
        // careers move; so do crabs. A housed crab whose job has drifted far
        // from their door takes a much-closer empty lot when they can cover
        // the move (a quit fisher shouldn't keep the promenade forever)
        // no deposit on a lateral move - you keep your tenancy, you just swap
        // lots. Charging it again would trap the poorest crabs in the exact
        // long commute that keeps them poor.
        if (c.p.boat == null) {
          const door2 = jobDoor(c), used2 = new Set(allCrabs().filter(k => !k.p.homeless).map(k => k.p.house));
          let near = -1, nearD = Math.abs(HOUSE_XS[c.p.house] - door2) - 400;   // only for a real saving
          for (let h = 0; h < HOUSE_XS.length; h++) {
            if (used2.has(h)) continue;
            const d = Math.abs(HOUSE_XS[h] - door2);
            if (d < nearD) { nearD = d; near = h; }
          }
          if (near >= 0) {
            c.p.house = near;
            logHome(c, "MOVED TO " + placeName(c.p) + " - CLOSER TO WORK");   // DIARY
            today.moved.push(c.p.name + " MOVED CLOSER TO WORK");
            popText("CLOSER TO WORK", HOUSE_XS[near] + 8, 100, [140, 255, 160]);
          }
        }
      } else {
        c.p.homeless = true;
        logHome(c, "COULDN'T MAKE RENT - LOST THE HOUSE");   // DIARY: the night a run turns
        evictedNames.push(c.p.name); today.moved.push(c.p.name + " -> SHELTER");
        popText(c.p.name + " LOST THEIR HOUSE", c.x - 12, FLOOR_Y - 34, [255, 120, 120]);
      }
    }
    if (evictedNames.length) {
      toast = { text: evictedNames.join(", ") + " MOVED TO THE SHELTER", t: 6 };
      sfx.angry();
    }
    // 2a2. npc payroll: owners pay their staff from the till - or lose them to the pier
    for (const c of npcs) {
      const emp = c.p.employer;
      if (!emp) continue;
      const o = OWNERS[emp];
      if (c.p.sick && !c.workedToday) continue;      // sick day: no work, no pay - same deal as the crew
      if (awayToday(c) && !c.workedToday) continue;  // day off (or a walk-out): unpaid, but the job is safe
      const npcDue = Math.round(basePayToday(c)) + Math.round(otPayToday(c));   // peer owners buy hours at the same rate, premium included
      if (o && o.till >= npcDue) { o.till -= npcDue; c.p.wallet += npcDue; crabLog(c, "money", "WAS PAID $" + $d(npcDue) + " BY " + o.name, 0); }   // DIARY
      else {
        crabLog(c, "life", "QUIT - " + (o ? o.name : "THE BOSS") + " COULDN'T PAY", 0);   // DIARY
        // ...and they need somewhere to stand when they get there. layOff()
        // and townAfterDeath() both hand a returning fisher a free rail spot;
        // this third path back to the pier - an owner who cannot make payroll
        // - did not, so the quitter fished from wherever they happened to be.
        c.p.job = "fishing"; c.p.employer = null; rosterGen++;
        if (!c.fishSpot) c.fishSpot = freeFishSpot();
        today.moved.push(c.p.name + " QUIT - BACK TO THE PIER");
        toast = { text: c.p.name + " QUIT: " + (o ? o.name : "THE BOSS") + " COULDN'T PAY", t: 6 };
      }
    }
    // 2a3. the money has landed (or hasn't): every crab on a payroll compares
    // tonight's wage with what the water, the shop next door and the crab at
    // the next station are getting, and grumbles, asks around or goes.
    runWageRelations();
    // 2a4. THE TOWN HALL settles before the landlords do - the shelter's rent
    // and its pot are the town's bill, and a levy is a cost of trading rather
    // than something a shop pays out of what is left after everything else.
    // Placed here on purpose: the player's own levy lands BEFORE step 3's rent
    // and credit line, which is the conflict of interest with teeth in it.
    runTownHall();
    // 2b. peer owners settle their own books on the same line of credit:
    // shortfalls draw on the line and interest compounds exactly as it does
    // for the player. A settlement that misses the minimum (or can't even
    // draw the night's bill) is a STRIKE against that lease; SALE_CFG.STRIKES
    // in a row and the business CLOSES and goes up for sale (see the business
    // failure & succession block). The debt is no longer quietly written off.
    for (const b of Object.keys(BIZ)) {
      const oid = bizOwner(b);
      if (!oid || oid === "player") continue;
      const o = OWNERS[oid];
      if (!o || day <= 1) continue;
      // an owner who died settles nothing: the shop is shut, not in arrears.
      // runSuccession() below sweeps it onto the market (listForSale "gone").
      if (o.gone) continue;
      if ((o.darkT || 0) > 0) {   // legacy saves only: run the old timer out
        if (--o.darkT === 0) toast = { text: BIZ[b].name + " IS BACK IN BUSINESS", t: 6 };
        continue;
      }
      // a rival's WAR CHEST comes out before a rent is missed: saving up to buy
      // the shop next door must never be the thing that shuts your own
      const nf = settleCreditLine(o.credit || 0, o.till, BIZ[b].rent);
      o.credit = nf.bal; o.till = Math.max(0, nf.funds);   // interest lands either way; a missed bill stays owed
      if (nf.ok && !nf.missedMin) bizStrike[b] = 0;        // a clean night wipes the slate
      else if (noteLeaseMiss(b, o)) continue;              // shutters up: nothing left to manage tonight
      runHoursPolicy(b);   // books settled: the day's demand signals tune tomorrow's hours
      runWagePolicy(b);    // ...and the day's labour signals tune tomorrow's wage
    }
    // the day's takings are booked, empty shops go on the market, and the
    // market clears - one call, all of it in its own block above
    runSuccession();
    // ...and the peer owner who wants a shop that is NOT for sale reads her
    // own books, one move a night (see THE RIVALRY)
    runRivalAmbition();
    // ...and the one who came for the hotel and got it reads hers (THE HOTELIER)
    runHotelier();
    // ...and both ACCOMMODATION ladders: the Driftwood's owner reads the guests
    // she had to turn away, and the mayor reads the crabs who found no cot.
    runAccommodation();
    for (const c of npcs) {
      c.p.hunger = Math.min(Q20, (c.p.hunger || 0) + qn(0.1));
    }
    // 2.5 epidemiology: neglect breeds illness; illness spreads; rest + care cures
    {
      const everyone = allCrabs();
      const sickNow = everyone.filter(k => k.p.sick);
      for (const k of everyone) {
        if (k.p.sick) continue;
        // ONE INSTANT SAMPLE of the four needs, and it is the fairest of the
        // three rules that were measured against each other - see illRisk.
        let risk = illRisk(k);
        for (const s2 of sickNow) {
          const coworkers = s2.workBiz === k.workBiz && k.dsC !== DS.home && !s2.p.npc;
          const shelterMates = k.p.homeless && s2.p.homeless;
          if (coworkers || shelterMates) risk += 0.08;
        }
        // THE ROLL'S OWN VIEW OF THE TOWN, for a measurement rig that needs
        // the DENOMINATOR as well as the cases - every at-risk crab-night, who
        // they were, what shift they drew and what the roll read off them.
        // This is the seam the shift-vs-illness question was settled on
        // (tools/shiftill.mjs); reasoning about it from the code got the wrong
        // answer twice. Off unless a rig asked for it, and it consumes no RNG,
        // so a build with it on is behaviour-identical to one without.
        if (window._stats && window._stats.rollLog) window._stats.rollLog.push({
          day, name: k.p.name, shift: k.p.shift, npc: !!k.p.npc,
          homeless: !!k.p.homeless, wallet: Math.round(k.p.wallet || 0),
          risk: +risk.toFixed(5),
          now: { hunger: +(k.p.hunger || 0).toFixed(3), thirst: +(k.p.thirst || 0).toFixed(3),
                 dirt: +((k.p.dirt || 0) / Q20).toFixed(3), tired: +((k.p.tired || 0) / Q20).toFixed(3) },
        });
        if (risk > 0 && srand() < Math.min(0.5, risk)) {
          k.p.sick = { days: 0 }; today.sick.push(k.p.name);
          logFellIll(k);   // DIARY
          if (window._stats) {
            const why = [];
            if ((k.p.hunger || 0) >= qn(0.9)) why.push("hunger");
            if ((k.p.thirst || 0) >= qn(0.9)) why.push("thirst");
            if ((k.p.dirt || 0) >= qn(0.9)) why.push("dirt");
            if ((k.p.tired || 0) >= qn(0.9)) why.push("exhaustion");
            if (why.length === 0) why.push("contagion");
            window._stats.causes = window._stats.causes || {};
            for (const w of why) window._stats.causes[w] = (window._stats.causes[w] || 0) + 1;
          }
          popText(k.p.name + " FELL ILL", k.x - 10, FLOOR_Y - 34, [130, 220, 110]);
          if (window._stats) window._stats.infections = (window._stats.infections || 0) + 1;
        }
      }
      for (const k of everyone) {
        if (!k.p.sick) continue;
        k.p.sick.days++;
        // THE CARED SEAM: a graded ladder, not a coin flip (see CARE_LANES).
        // A crab who spent the day resting at home, fed and hydrated, does
        // measurably better - and their own bed beats a shelter cot.
        const lane = careLane(k), care = CARE_LANES[lane];
        const tier = k.p.homeless ? "cot" : k.p.boat != null ? "boat" : "house";
        if (srand() < care.cure) {
          const dur = k.p.sick.days;
          k.p.sick = null; today.recovered.push(k.p.name);
          crabLog(k, "need", "GOT BETTER AFTER " + dur + " DAY" + (dur === 1 ? "" : "S") + " ILL", 0);   // DIARY
          popText(k.p.name + " RECOVERED!", k.x - 12, FLOOR_Y - 34, [140, 255, 160]);
          if (window._stats) {
            window._stats.recoveries = (window._stats.recoveries || 0) + 1;
            (window._stats.illness = window._stats.illness || [])
              .push({ day, name: k.p.name, days: dur, lane, tier, out: "well" });
          }
        } else if (k.p.sick.days >= deathArmsAt(lane) &&
            srand() < Math.min(0.75, care.die + 0.12 * Math.max(0, k.p.sick.days - 4))) {
          if (window._stats) (window._stats.illness = window._stats.illness || [])
            .push({ day, name: k.p.name, days: k.p.sick.days, lane, tier, out: "died", npc: !!k.p.npc });
          killCrab(k);   // the tide takes them - crew and townsfolk alike
        } else if (k.p.sick.days >= deathArmsAt(lane) - 1) {
          // SEE IT COMING. The roll arms on deathArmsAt(lane); the town is told
          // the night before, by name, so the player has a whole day to act
          // (grant the sick day, get food and water into them, send them to
          // their own bed - the care ladder is what this warning points at).
          if (k.p.gravDay !== day) {
            k.p.gravDay = day;
            crabLog(k, "peril", "GRAVELY ILL - DAY " + (k.p.sick.days + 1) + ", NEEDS CARE", 0);   // DIARY
            today.critical.push(k.p.name);
            toast = { text: k.p.name + " IS FADING - THEY NEED REST AND CARE", t: 8 };
            popText("GRAVELY ILL", k.x - 14, FLOOR_Y - 34, [255, 150, 130]);
          }
        }
      }
      for (const k of allCrabs()) k.p.restT = 0;   // convalescence is banked one day at a time
    }
    // 2.6 IDLE HANDS, THE LATE STAGE: THE WALK-OUT (B3).
    // Boredom is the one need with no free cure and no death roll. What it has
    // instead is this: a crab pinned past WALKOUT_AT at WALKOUT_DAYS
    // settlements running has simply had enough, and takes tomorrow off. No
    // commute, no shift, NO WAGE - and nobody covers it, because nobody was
    // told. Real stakes, no death, and the player gets a full day's warning by
    // name, so it is a thing they could have fixed (an arcade, an errand, a
    // rota change) rather than a thing that happened to them.
    for (const k of allCrabs()) {
      // a rough night bridges midnight, so it is reported at the NEXT
      // settlement - and cleared, so it is reported exactly once
      if (k.p.roughLast && k.p.roughLast >= day - 1) {
        today.moved.push(k.p.name + " SLEPT ROUGH - NO REST BANKED");
        k.p.roughLast = 0;
      }
      if (walkoutToday(k)) today.moved.push(k.p.name + " NEVER CAME IN - NO WAGE");
      k.p.boredDays = (k.p.bored || 0) >= WALKOUT_AT ? (k.p.boredDays || 0) + 1 : 0;
      if ((k.p.boredDays || 0) < WALKOUT_DAYS || k.p.walkout === day + 1 || patOff("walkout")) continue;
      if (k.p.sick || dayOffIdx(k) === weekdayIdx(day + 1)) continue;   // already off - it'd prove nothing
      k.p.walkout = day + 1; k.p.walkoutWhy = "bored"; k.p.boredDays = 0;
      today.walked.push(k.p.name);
      toast = { text: k.p.name + " HAS HAD ENOUGH - TAKING TOMORROW OFF", t: 8 };
      popText("I NEED A DAY", k.x - 14, FLOOR_Y - 34, [150, 150, 210]);
      // ONE SHAPE FOR ONE COUNTER. (Found independently on two branches the
      // same night, which is a fair sign of how load-bearing it was.) The pay walkout (runWageRelations) records a
      // ROW here and this one used to record a COUNT, so a town that took a
      // bored walkout and then a pay walkout threw
      // `_stats.walkouts.push is not a function` and killed the seed - which
      // is a headless-only path, but the headless matrix is how every balance
      // number in PLAN is measured. Both write rows now.
      if (window._stats) (window._stats.walkouts = window._stats.walkouts || [])
        .push({ day: day + 1, name: k.p.name, why: "bored" });
    }
    // the day's labor policy: peer owners (and delegating players) make at
    // most one move each, on the same convergent-rules pattern as SUDSY's hours
    for (const b of Object.keys(BIZ)) if (bizUnlocked(b)) runLaborPolicy(b);
    // 3. property rents + loan service (THE credit hook): a shortfall draws
    // on the line of credit instead of instant eviction; interest compounds
    // and the minimum payment auto-collects inside settleCreditLine.
    // ok:false is the new cliff - BANKRUPT (see CREDIT_CFG).
    const rent = totalRent();
    const fin = settleCreditLine(credit.bal, coins, rent);
    if (fin.ok) {
      credit.bal = fin.bal; coins = fin.funds;
      earnHist.push({ t: viewT, amt: fin.drew - rent - fin.paid });
      const offNames = allCrabs().filter(c => offToday(c)).map(c => c.p.name);
      report = {
        day, served: today.served, revenue: Math.round(today.revenue), rage: today.rage,
        wages, rent, sick: today.sick.slice(0, 3), died: today.died.slice(0, 2),
        critical: today.critical.slice(0, 2), walked: today.walked.slice(0, 3),
        recovered: today.recovered.slice(0, 2), moved: today.moved.slice(0, 2),
        rival: (today.rival || []).slice(0, 2),
        // THE OFFICE, on the nightly report, because it bills the player now:
        // what the town took off your till, what came back when the shelter
        // bought its bowls off your own counter, and whether the pot is on.
        hallPaid: Math.round(townFund.youPaid), hallGot: Math.round(townFund.youGot),
        bowls: townFund.bowls, potShut: shelterShut(), potWhy: townFund.potWhy, mayor: hall.mayor,
        hallPol: policyLine(hall.policy), hallOwn: playerMayor(),
        off: offNames.slice(0, 4).join(", "),
        repStart: repPts(today.repStart), repEnd: repPts(rep),
        best: Object.keys(today.byCrab).sort((a, b) => today.byCrab[b] - today.byCrab[a])[0],
        bestN: 0, coins: Math.round(coins),
        tipsShared: Math.round(today.tipsShared || 0), bused: today.bused || 0,
        drew: fin.drew, interest: fin.interest, loanPaid: fin.paid, debt: Math.round(credit.bal),
        backPaid, missedPay, missedN, owed: backPayDue(),
      };
      if (report.best) report.bestN = today.byCrab[report.best];
      reportT = 11;
      // ...and the day's OTHER page, queued rather than shown: the report is up
      // and this waits its turn behind it (see departTick in the frame loop).
      departQ = departBuild();
      const dl = (window.dayLog || [])[(window.dayLog || []).length - 1];
      if (dl) dl.after = Math.round(coins);   // forecaster: post-settlement till
      if (rent > 0) popText("-$" + $d(rent) + " RENT", BIZ.shack.door, 110, [255, 120, 120]);
      if (fin.drew > 0) popText("+$" + $d(fin.drew) + " ON CREDIT", BIZ.shack.door, 100, [255, 190, 90]);
      sfx.buy(); save();
    } else {
      gameOver = true; bankrupt = true; toast = null; save();
      if (music) { music.pause(); music = null; }
      sfx.angry();
    }
  }

  if (screen === "play" && !gameOver) updateBankWarning();
}

// the announcement half of what drawFloaters used to do: lifetimes are SIM
// (a float belongs to the moment in the day that produced it), rendering is
// not. Headless towns now age their floats too, instead of hoarding every
// pop-up since day one.
function ageFloaters(dt) {
  for (const f of floaters) { f.t -= dt; f.y = (f.y * Q8 - idiv(14 * Q8 * dtT, TICK_HZ)) / Q8; }   // rise on the grain
  floaters = floaters.filter(f => f.t > 0);
}

function simTown(dt) {
  poolReap();
  if (!gameOver) {
  updateBus(dt);
  if (tmin >= 7.5 * 60 && hireDay !== day) { hireDay = day; runJobBoard(); }
  updatePoll(dtT);  // the polls shut on the clock, and then the count runs on it too
  updateCustomers(dt);
  runChatter(dt);   // its own pass over the crab list - NOT folded into collide()
  for (const c of allCrabs()) {
    c.animT += dt;
    c._stepped = false;
    // A CONVERSATION STOPS THE DAY. Nothing else runs while two crabs talk -
    // not the schedule, not the kitchen, not the commute. That is the price of
    // boredom's only free cure, and it is the whole reason the cure is allowed
    // to exist at all (PLAN, THE SELF-HEALING RULE: it costs time, never money).
    if (c.dsC === DS.chat) { updateChat(c, dt); maybeQuip(c, dt); continue; }
    updateSchedule(c, dt);
    if (c.dsC === DS.toWork || c.dsC === DS.toHome) updateCommute(c, dt);
    else if (c.dsC === DS.toErrand || c.dsC === DS.errand) updateErrand(c, dt);
    else if (c.dsC === DS.atTap) updateTap(c, dt);
    else if (c.dsC === DS.atBall) updateBall(c, dt);
    else if (c.dsC === DS.selfCook) updateSelfCook(c, dt);
    else if (c.dsC === DS.working && c.p.job === "fishing") updateFishing(c, dt);
    else if (c.dsC === DS.working) updateKitchen(c, dt);
    else if (c.dsC === DS.directed) updateDirected(c, dt);
    else if (c.dsC === DS.home) updateHome(c, dt);
    updateStuck(c, dt);
    maybeQuip(c, dt);
  }
  if (followCust && !customers.includes(followCust)) followCust = null;   // they went home
  if (dossier && !dossier.p && !customers.includes(dossier)) dossier = null;
  // a selected tourist who leaves town (or a crab who dies) drops the selection
  if (sel && (sel.p ? !allCrabs().includes(sel) : !customers.includes(sel))) sel = null;
  const reading = boardView || manage || saveView || dossier || helpView;
  if (reportT > 0 && !ffSleep && !reading) reportT -= dt;   // waits out a sun-skip, and waits behind an open card
  // THE DAY'S SECOND PAGE. It comes up when the report goes down - by the click
  // that closed it or by its own timer - so the end of the day is one moment
  // with one gesture through it rather than two cards fighting for the screen.
  if (departQ && reportT <= 0) { depart = departQ; departQ = null; departPage = 0; departT = DEPART_T; }
  if (departT > 0 && !ffSleep && !reading) departTick(dt);
  if (toast && (reading || departT > 0)) toast.t = Math.max(toast.t, 0.4);   // a toast holds while you read, then plays out
  if (newConfirmT > 0) newConfirmT -= dt;
  if (toast) { toast.t -= dt; if (toast.t <= 0) toast = null; }
  saveT += dt; if (saveT > 5) { saveT = 0; save(); }
  }

  ageFloaters(dt);
  if (!gameOver && !_fNoColl) collide(dt);
}

function introFrame() {
  window._viewCalls = (window._viewCalls || 0) + 1;
    camX = clampCam(BIZ.shack.x0 - 20);
    drawBG(); drawTown();
    for (const c of crabs) drawCrab(c);
    drawIntro();
}

function titleFrame(dt) {
  window._viewCalls = (window._viewCalls || 0) + 1;
    // THE START SCREEN HAS ITS OWN TRACK, and it is the one named after it.
    playRole("title");
    if (newConfirmT > 0) newConfirmT -= dt;
    // attract mode: slow ping-pong pan across the town
    const span = WORLD_W - W, s = (viewT * 9) % (2 * span);
    camX = s < span ? s : 2 * span - s;
    // view-side sim theatre runs on the VIEW stream (slice 5): the wander's
    // own draw and every draw inside the re-entered sim code land on vrand,
    // and the sim stream is untouched while the title runs.
    onViewStream(() => {
      updateBus(dt);
      for (const c of crabs) {
        c.animT += dt; maybeQuip(c, dt);
        if (c._wt == null || Math.abs(c.x - c._wt) < 2)
          c._wt = Math.max(20, Math.min(WORLD_W - 30, c.x + Math.floor(srand() * 90 * Q8) / Q8 - 45));   // same draw, on the grain
        else stepTo(c, c._wt, 11 * Q8, dt, 158);
      }
    });
    drawBG(); drawTown(); drawBus();
    for (const c of crabs) drawCrab(c);
    drawNight();
    drawTitle();
    drawSaveScreen();
    drawHelp();   // HOW TO PLAY is readable before the first day, which is the point
}

// the follow lerp, named so the suite can drive the view camera contract
// from a frozen state snapshot - the seam "view is a reader" made testable
function followCam(dt) {
  const followed = followNpc || followCust || (followIdx >= 0 && crabs[followIdx]);
  if (followed) {
    const t = clampCam(followed.x - W / 2 + 8);
    camX += (t - camX) * Math.min(1, dt * 5);
    if (window._probeCam) (window._camProbe = window._camProbe || []).push([followed.x, camX, dt]);   // debug seam, _vpLerped family
  }
}
window._dbgFollow = (i) => { followIdx = i; followNpc = null; followCust = null; return { n: crabs.length, f: followIdx, scr: screen }; };   // debug seam: the card click, addressable
function viewFrame(dt) {
  window._viewCalls = (window._viewCalls || 0) + 1;
  followCam(vpCamDt);   // the camera's own clock (headless never enters viewFrame; the suite drives followCam directly)
  drawBG();
  drawTown();
  drawBus();
  // painter's pass: stations, customers, crabs interleaved by baseline
  const paint = [];
  for (const key of Object.keys(BIZ)) {
    if (!bizUnlocked(key)) continue;
    const b = BIZ[key];
    for (const kind of Object.keys(b.stations)) {
      const cap = stationCap(key, kind);
      for (let i = 0; i < cap; i++) {
        const st = b.stations[kind][i];
        paint.push({ base: st.y, f: () => drawStation(key, kind, i) });
      }
    }
  }
  for (const key of Object.keys(BIZ)) {
    if (!bizUnlocked(key)) continue;
    const tables = bizTables(key);
    if (tables) for (const t of tables) paint.push({ base: t.y, f: () => {
      wblit(PICNIC_TABLE, t.x, t.y - PICNIC_TABLE.h);
      if (t.dishes > 0) wblit(DISHES[t.dishes - 1], t.x + 6, t.y - PICNIC_TABLE.h - DISHES[t.dishes - 1].h + 1);
      // an abandoned table wears the stalls' crumb-flecks, so "waiting to be
      // bused" reads at a glance from across the boardwalk
      if (t.dirty) {
        px(ctx, t.x + 3 - camX, t.y - 2, [200, 180, 120]);
        px(ctx, t.x + 13 - camX, t.y - 1, [180, 160, 110]);
        px(ctx, t.x + 9 - camX, t.y - 3, [200, 180, 120]);
      }
    } });
    const stalls = BIZ[key].stalls;
    // HOTEL ROOMS are stalls too, but they read as doors on a back wall: the
    // lamp is on when a guest is in residence, and an unmade bed (the DIRTY
    // flag housekeeping is about to clear) hangs its own little card.
    if (stalls && BIZ[key].lodging) { for (const t of stalls) paint.push({ base: t.y, f: () => {
      // ...and the forecourt's huts are stalls too (ACCOMMODATION UPGRADES):
      // same list, same cycle, their own silhouette.
      if (t.cabana) { drawCabana(t, stalls.indexOf(t) + 1); return; }
      const guest = t.occupant && t.occupant.visitor ? t.occupant : null;
      const lit = guest && (guest.stC === VS.inRoom || darkness() > 0.4);
      wblit(HOTEL_DOOR[lit ? 1 : 0], t.x, t.y - HOTEL_DOOR[0].h);
      // the room number on the transom, and a Z over the door of an occupied
      // one. Both sit in the 4px of wall between the awning and the door head -
      // anything higher is painted over by the shopfront's own roofline.
      const n = stalls.indexOf(t) + 1;
      const nx = t.x + 7 - camX;
      if (nx > -12 && nx < W) smallText(ctx, "" + n, nx, t.y - HOTEL_DOOR[0].h - 5, [70, 60, 90]);
      if (guest && guest.stC === VS.inRoom) {
        const ph = ((viewT * 0.7 + t.x * 0.01) % 1);
        smallText(ctx, "Z", t.x + 12 - camX, t.y - HOTEL_DOOR[0].h + 3 - ph * 4, [190, 205, 255]);
      }
      if (t.dirty) {   // the maid hasn't been round
        px(ctx, t.x + 3 - camX, t.y - 2, [220, 190, 130]);
        px(ctx, t.x + 8 - camX, t.y - 1, [200, 170, 120]);
        px(ctx, t.x + 12 - camX, t.y - 2, [220, 190, 130]);
      }
    } }); continue; }
    if (stalls) for (const t of stalls) paint.push({ base: t.y, f: () => {
      const bathing = t.occupant && t.occupant.stC === VS.showering;
      wblit(STALL[bathing ? 1 : 0], t.x, t.y - STALL[0].h);
      if (bathing) {   // feet peeking under the curtain
        const oc = t.occupant, cul = !oc.isCrab && visCulture(oc);
        const pcol = oc.isCrab ? oc.crab.p.color : (oc.p ? oc.p.color : oc.color);
        const col = cul ? cultureSlotCol(cul, pcol, 0) : CRAB_COLORS[(pcol || 0) % CRAB_COLORS.length][0];
        wrect(t.x + 5, t.y - 3, 2, 2, col);
        wrect(t.x + 9, t.y - 3, 2, 2, col);
      }
      if (bathing) {   // the bather's head bobs over the curtain
        const oc = t.occupant, cul = !oc.isCrab && visCulture(oc);
        const pcol = oc.isCrab ? oc.crab.p.color : (oc.p ? oc.p.color : oc.color);
        const bob = Math.round(Math.sin(viewT * 3 + t.x) * 1.5);
        const hy = t.y - STALL[0].h + 4 + bob;
        if (cul && cul.bather) {
          // the culture declares its own over-the-curtain silhouette: a rect
          // list [dx, dy, w, h, slotIdx] relative to (stall x, head line)
          for (const r of cul.bather)
            wrect(t.x + r[0], hy + r[1], r[2], r[3], cultureSlotCol(cul, pcol, r[4]));
        } else {
          const pal = CRAB_COLORS[(pcol || 0) % CRAB_COLORS.length];
          wrect(t.x + 5, hy, 6, 3, pal[0]);                    // wet shell dome
          wrect(t.x + 6, hy - 1, 4, 1, pal[0]);
          wrect(t.x + 6, hy - 3, 1, 2, pal[1] || pal[0]);      // eyestalks
          wrect(t.x + 9, hy - 3, 1, 2, pal[1] || pal[0]);
          px(ctx, t.x + 6 - camX, hy - 3, [255, 255, 255]);    // happy wet eyes
          px(ctx, t.x + 9 - camX, hy - 3, [255, 255, 255]);
        }
      }
      if (bathing) {   // suds drift up over the curtain while the water runs
        for (let i = 0; i < 3; i++) {
          const ph = (viewT * 0.6 + i * 0.33 + t.x * 0.013) % 1;
          if (ph > 0.85) continue;
          const sx = t.x + 3 + i * 4 + ((Math.sin(viewT * 1.5 + i * 2.1) * 2) | 0);
          const s = ph < 0.5 ? 2 : 1;
          wrect(sx, t.y - STALL[0].h - 2 - ph * 8, s, s, i % 2 ? [96, 200, 255] : [88, 205, 188]);
        }
      }
      if (t.dirty) { px(ctx, t.x + 3 - camX, t.y - 2, [130, 220, 110]); px(ctx, t.x + 7 - camX, t.y - 1, [110, 190, 110]); px(ctx, t.x + 11 - camX, t.y - 2, [130, 220, 110]); }
    } });
  }
  for (const k of customers) paint.push({ base: (k.stC === VS.dining || k.stC === VS.seatedWaiting) && k.table ? (k.table.y + 1) : (k.isCrab ? 165 : custY(k)), f: () => drawCustomer(k) });
  // ...and the ring goes wherever the body goes. drawCustomer hands a bathing
  // or sleeping guest over to the stall and the hotel door and draws nothing
  // itself, so without these two the ring blinks on bare wall.
  if (sel && !sel.hidden && sel.stC !== VS.showering && sel.stC !== VS.inRoom) paint.push({ base: sel.y - 0.1, f: () => {
    // a soft ring under whoever you've picked: it stays put while you pan
    const bx = sel.x + 8 - camX, by = (sel.p ? sel.y : custY(sel) - 4 - 26 * ((sel.climb || 0) / 4096)) + 2;
    const blink = 0.55 + 0.45 * Math.sin(viewT * 4);
    const col = [Math.round(120 + 135 * blink), Math.round(200 + 30 * blink), 120];
    for (let i = -6; i <= 6; i++) {
      const t2 = i / 6, dy = Math.round(2 * (1 - t2 * t2));
      px(ctx, bx + i, by - dy, col); px(ctx, bx + i, by + dy, col);
    }
  } });
  for (const c of allCrabs()) paint.push({ base: c.csC === CS.drive && (c.dsC === DS.toWork || c.dsC === DS.toHome) ? ROAD_Y1 : c.y, f: () => drawCrab(c) });
  paint.push({ base: FLOOR_Y, f: drawLandlord });
  // THE BALL IS A THING ON THE SAND, so it belongs in the paint list with the
  // crabs rather than in the terrain pass. (Matt: "the beach ball needs
  // screenshot testing, I don't see it." He could not see it: it was drawn
  // THIRD in drawTown, ahead of the houses and every shopfront, and BALL_X
  // 1290 is inside the CRAB SHACK's own span (1220-1560) - so the shack's
  // decking painted over it in every frame of every day since it landed.
  // Moving it later inside drawTown was not enough either; the shopfronts
  // come after that too. Sorted by y with everything else is the position
  // that cannot be wrong: it composites against the crabs playing with it
  // instead of racing them.)
  paint.push({ base: BALL_Y + 1, f: drawBeachBall });
  paint.sort((a, b) => a.base - b.base);
  for (const e of paint) e.f();
  drawForSaleSigns();   // boards go over the furniture, and the price has to read from the street
  drawRivalSigns();     // ...and so do a rival's offer, her competition and her own asking price
  drawSwoop();
  drawFloaters(dt);
  {  // directed-crab marker: a bouncing flag where the followed crab was sent
    const fc = followIdx >= 0 && crabs[followIdx];
    if (fc && fc.order && fc.dsC === DS.directed && fc.order.idleT < 0) {
      const mx = fc.order.x + 6 - camX;
      if (mx > -8 && mx < W + 8) {
        const my = fc.order.y - 16 - Math.abs(Math.sin(viewT * 5)) * 3;
        rect(ctx, mx, my, 1, 9, [255, 255, 255]);        // pole
        rect(ctx, mx + 1, my, 5, 4, [255, 216, 96]);     // pennant
        px(ctx, mx + 6, my + 1, [255, 216, 96]);
        px(ctx, mx, fc.order.y - 6, [255, 216, 96]);     // planted spot
      }
    }
  }
  drawHirePointer();   // the new hire, pointed at, in the town rather than on a list
  drawNight();
  drawNav();      // HUD, so: after the night wash - the map never goes dark
  // ---- THE WORLD'S OWN CHIPS, AND THEY GO UNDER EVERY CARD (Matt, 2026-08-20:
  // "the warning messages need to be painted under the menu please; too much
  // stuff pops up over menus"). These three used to be drawn AFTER drawManage
  // and drawDossier, which put the REP chip through the top-right corner of the
  // management card, the skip-to-morning sun inside it, and a BLINKING RED
  // BANKRUPT warning across its bottom edge - on a card the player had opened
  // precisely to do something about being bankrupt.
  //
  // Painting them here does not hide them: with no card open the frame is
  // identical, because nothing else is drawn over that part of the world. It
  // only means a card the player opened OWNS THE SCREEN while it is open, which
  // is the same rule drawToast and drawFollowCard already follow.
  {  // town reputation chip, top-right of the world
    const rTxt = "REP " + repPts(rep);
    const rw = smallTextWidth(rTxt) + 8;
    rect(ctx, W - rw - 2, 2, rw, 10, [30, 20, 36]);
    smallText(ctx, rTxt, W - rw + 2, 4, rep >= 50000 ? [140, 220, 140] : rep >= 25000 ? [220, 205, 185] : [235, 130, 130]);
  }
  {  // the little sun: skip to morning (top-right, under the REP chip)
    const on = ffSleep;
    rect(ctx, W - 24, 14, 22, 13, [30, 20, 36]);
    rect(ctx, W - 23, 15, 20, 11, on ? [255, 216, 96] : [70, 58, 66]);
    const sc = on ? [140, 90, 20] : [255, 216, 96];
    rect(ctx, W - 16, 18, 5, 5, sc);                       // sun core
    px(ctx, W - 14, 16, sc); px(ctx, W - 14, 24, sc);      // rays
    px(ctx, W - 18, 20, sc); px(ctx, W - 10, 20, sc);
    px(ctx, W - 17, 17, sc); px(ctx, W - 11, 17, sc);
    px(ctx, W - 17, 23, sc); px(ctx, W - 11, 23, sc);
    if (on) smallText(ctx, "ZZZ", W - 44, 17, [255, 230, 120]);
  }
  {  // line-of-credit chips, bottom-right of the world - now stacking up from
     // the nav strip's chip row, whose left end carries MANAGE and TOWN
    let cy = PANEL_Y - NAV_H - 12;
    if (bankHorizon <= CREDIT_CFG.CHIP_DAYS && !gameOver) {
      const wTxt = bankHorizon <= 0 ? "BANKRUPT TONIGHT!" : "BANKRUPT IN " + bankHorizon + "D";
      const ww = smallTextWidth(wTxt) + 8;
      const blink = ((viewT * 2) | 0) % 2;
      rect(ctx, W - ww - 2, cy, ww, 10, blink ? [150, 30, 30] : [60, 16, 20]);
      smallText(ctx, wTxt, W - ww + 2, cy + 2, blink ? [255, 230, 230] : [235, 130, 130]);
      cy -= 12;
    }
    if (credit.bal > 0) {
      const dTxt = "DEBT $" + fmt(Math.round(credit.bal)) + "/" + creditLimit();
      const dw = smallTextWidth(dTxt) + 8;
      rect(ctx, W - dw - 2, cy, dw, 10, [30, 20, 36]);
      smallText(ctx, dTxt, W - dw + 2, cy + 2, [255, 190, 90]);
    }
  }

  drawJobBoard();
  // A READING SURFACE OWNS THE SCREEN (owner report: "events appear at same
  // time as ledger and block it out"). The day report and toasts wait their
  // turn - reportT is paused below rather than burned down behind the card,
  // so nothing is missed, it just arrives when you close what you opened.
  if (!boardView && !manage && !saveView && !dossier) drawReport();
  if (!boardView && !manage && !saveView && !dossier && reportT <= 0) drawDepart();
  drawManage();
  drawDossier();   // above the management card: a census row opens a dossier ON TOP of it
  drawFollowCard();
  drawBrainPanel();
  drawCycler();   // < crab > : step the selection (and the camera) through the town
  drawSendChip();   // SEND: the order gesture every device can make
  drawPanel();
  drawNavChips();      // MANAGE / TOWN sit IN the panel now, so they go on after it
  drawShopTip();       // hangs off the bottom of the world, pointing at the grid it explains
  drawHireCard();
  if (!boardView && !manage && !saveView && !dossier && !helpView && departT <= 0) drawToast();   // reading surfaces own the screen
  // ...AND SO DOES THE END, either kind of it: the ferry ending and the
  // bankruptcy card are the same thirty-one seconds of somebody telling you how
  // it went. (Placed with the draw rather than at the moment of death because a
  // town can also be LOADED into its own ending - see winRec - and a reloaded
  // win should sound like the one you played.)
  if (gameOver || won) playRole("end");
  if (gameOver) drawGameOver();
  drawSaveScreen();
  drawHelp();          // the last word: HOW TO PLAY sits over everything, including game over
  if (window.MergeMode) MergeMode.frame(dt);
}

// THE SWAP WINDOW. Interpolated grains go into the live planes for exactly
// one viewFrame call and come back out bit-for-bit. A fast-forward frame
// (more than 2 ticks) skips the swap entirely - at 6x the eye cannot see
// tick granularity, and the sun-skip advances 12 a step.
function vpSwapIn() {
  if (vpTicks > 2) return;
  const a = msAcc / 50;   // view float, like camX - the sim never sees it
  VP_RX.set(PXQ); VP_RY.set(PYQ); VP_RW.set(PWYQ);
  for (let i = 0; i < POOL_MAX; i++) {
    const dx = PXQ[i] - VP_PX[i], dy = PYQ[i] - VP_PY[i];
    if (dx > VP_SNAPQ || dx < -VP_SNAPQ || dy > VP_SNAPQ || dy < -VP_SNAPQ) continue;   // teleport: draw the truth
    PXQ[i] = VP_PX[i] + Math.round(dx * a);
    PYQ[i] = VP_PY[i] + Math.round(dy * a);
    PWYQ[i] = VP_WY[i] + Math.round((PWYQ[i] - VP_WY[i]) * a);
  }
  vpSwapped = true;
  window._vpLerped = (window._vpLerped || 0) + 1;   // debug seam, same family as _viewCalls
}
function vpSwapOut() {
  if (!vpSwapped) return;
  PXQ.set(VP_RX); PYQ.set(VP_RY); PWYQ.set(VP_RW);
  vpSwapped = false;
}

// ========================================================== CRAB SCIENCE
// A LAB BENCH FOR A DETERMINISTIC TOWN. You give it a recipe - a seed, an
// opening plan, a stopping rule - and it lives the whole town out at speed,
// then lets you walk the timeline and step into any morning of it.
//
// THE ONE IDEA IT IS BUILT ON: a run is a RECIPE, NOT A RECORDING. The
// numeric era made the sim an integer machine whose every draw comes from one
// counted stream, so (seed, plan) fixes every day that follows. Re-running a
// recipe does not approximate the old run, it IS the old run. That is what
// makes a timeline scrubbable without storing one.
//
// WHY THE BROWSER NEEDS SEEDING AT ALL, which surprised me: headless towns are
// deterministic because the harness swaps in a seeded generator, but the
// SHIPPED game draws from the browser's own Math.random - a played town has
// never been reproducible, and never needed to be. A science run installs a
// seeded tap at `_rtap`, the one door slice 5 built for exactly this, and
// takes it back out when the run ends. Ordinary play is untouched.
//
// WHY KEYFRAMES ARE SAVE ENVELOPES: because the game already has a complete,
// maintained, migration-aware serialization of a town, and a second one would
// drift. Measured before building on it (tools/sci-probe.mjs): an envelope is
// NOT a bit-exact freeze of an instant - reload a town mid-walk and its crabs
// stand where the loader puts them, its session counters restart. That is
// right for a game save and it fixes the honest meaning of a scrub here: a
// keyframe is A MORNING YOU CAN GO BACK TO, not a paused frame. The lab
// therefore keys on day boundaries, where a town has no mid-stride to lose.
//
// THE RULING IT KEEPS: "interface opacity is a bug, economic uncertainty is
// the game" - so the lab never scries YOUR town. Science runs are their own
// towns, entered from the title, on their own seeds; PLAY THIS DAY hands you
// a copy to keep, and your saved towns are never rewound. See the close-out.
const SCI = {
  run: false,        // a run is executing (suppresses autosave; gates the seeded tap)
  seed: 1337,
  plan: 0,           // index into SCI_PLANS
  stopDay: 12,
  rule: 0,           // index into SCI_RULES
  days: [],          // one row per lived day: { day, env, coins, lifetime, rep, note }
  at: -1,            // which day row is materialized in the world, -1 = none
  drag: -1,          // finger/mouse scrub target while held, -1 = not scrubbing
  msg: "",
  origin: null,      // the boot envelope: every run's tick zero
};
const SCI_PLANS = [
  { name: "BUY NOTHING", buy: [] },
  { name: "A COOK", buy: ["chef"] },
  { name: "A COOK + A TABLE", buy: ["chef", "table"] },
];
// Stopping rules are a FIXED, NAMED set. Player-authored predicates are the
// cultureway tower's Layer-1 work (design/cs35-cultureway-substrate.md); the
// seam where they would plug in is this table and nothing else.
const SCI_RULES = [
  { name: "RUN THE FULL SPAN", hit: () => false },
  { name: "STOP IF THE TOWN FAILS", hit: () => gameOver },
  { name: "STOP AT 50% REPUTATION", hit: () => rep >= 50000 },
];
// mulberry32, the sim's own generator, for when the compiled kernel is off
function sciMul32(a) {
  let s = a | 0;
  return () => {
    s = (s + 0x6D2B79F5) | 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// Seed the SIM stream for a run. With the kernel armed the cursor lives in
// kernel memory and kernel-side consumers draw from it too, so seeding must
// go through the kernel or the two sides would walk different sequences -
// the same reason the harness seeds it there.
function sciSeedStream(seed) { simStreamAdopt(seed >>> 0); }   // a recipe's seed IS its opening cursor
function sciFreeStream() { _rtap = null; _rOwned = false; }   // back to the browser's own Math.random
// ONE SIM TICK, no view: the rung-1 seam is what makes this callable at all -
// simClock and simTown are the whole world, and drawing is a reader that a
// run at speed simply does not call.
function sciTick() {
  dtT = 1; T += 1;
  const dt = 1 / TICK_HZ;
  simClock(dt, 50);
  if (screen !== "play") return;
  simTown(dt);
}
// The opening plan, bought the way the seed matrices buy it: only what the
// town can afford while covering tonight's bill. Nothing is conjured - the
// standing ruling - so a plan is a PLAN, not a grant, and a poor town simply
// never gets there.
function sciBuy(plan) {
  for (const k of plan) {
    const u = UPS[k];
    if (!u || u.lvl >= u.max) continue;
    const crew = crabs.reduce((s, c) => s + Math.round(wageRate(c)), 0);
    const reserve = upCost(u) + crew + (k === "chef" ? bizWage("shack") : 0) + totalRent() + 7000;
    if (coins >= reserve) tryBuy(k);
  }
}
function sciDayNote() {
  if (gameOver) return "THE TOWN FAILED";
  if (won) return "THE FERRY!";
  const c = crabs.length + npcs.length;
  return c + (c === 1 ? " CRAB" : " CRABS") + ", REP " + repPts(rep) + "%";
}
// SHUTTLING A TOWN IN, which a scrub does over and over. Loading an envelope
// restores a town's DURABLE facts; it does not empty the room it walks into.
// Measured, each of these the hard way: the guests' bodies keep their pool
// slots (and the planes are read in slot order, so the same town under
// different slot numbers is a different arithmetic); the chairs they sat in
// keep their occupancy, which is a plane BIT rather than a field, so a fresh
// morning opened onto a full hotel; and the session ledgers - the earnings
// history the rival prices her ambition from, the queue's ticket counter -
// are what this RUNTIME has seen rather than anything a save carries.
// (rosterGen and furnGen are deliberately NOT reset: they are
// memo-invalidation counters, and winding one BACK would make a stale cache
// look current. Monotonic is their whole contract.)
function sciShuttle(envJson) {
  // THE SWEEP THAT USED TO LIVE HERE IS GONE, and that is the point. Every
  // clear this function performed - the pool and its free list, the furniture
  // occupancy bits, earnHist, the ticket counter, the townsfolk - is now
  // resetSession()'s job, run by load() itself the moment an envelope is
  // accepted. A workaround kept on top of a fix is how the next person learns
  // the wrong lesson, and the loader owed this to every caller, not just to
  // the bench.
  //
  // ONE THING STAYS, and it is not a leak: _stats is the HARNESS's observation
  // channel, not the town's state. The loader has no business zeroing a
  // counter the measuring tools own, so a bench run that wants clean stats
  // clears them here.
  if (window._stats) for (const k of Object.keys(window._stats)) {
    const v = window._stats[k];
    window._stats[k] = typeof v === "number" ? 0 : Array.isArray(v) ? [] : typeof v === "object" && v ? {} : v;
  }
  load(null, JSON.parse(envJson));
}
// LIVE THE WHOLE TOWN. Runs synchronously - a dozen days is about a second
// with the kernel armed, and a run that blocks briefly is honest where a
// half-drawn progress bar would be a lie about what the sim is doing.
function sciStart() {
  const plan = SCI_PLANS[SCI.plan].buy, rule = SCI_RULES[SCI.rule];
  SCI.run = true;
  SCI.days = []; SCI.at = -1; SCI.msg = "";
  // NO RESET HERE, ON PURPOSE. This runs once, at boot, on a world that has
  // never been anything else - the URL's seed was installed above the world's
  // own construction, so the founding crabs are already this recipe's crabs.
  // Chasing an in-place reset that could stand in for a clean boot is what
  // taught the lesson: the town came back identical by every measure I could
  // name - draws, positions, needs, ledgers, furniture, pool slots - and still
  // diverged on the twenty-four-thousandth tick, inside one visitor's mind,
  // over residue I had not thought to look for. A boot has no residue.
  screen = "play";
  let guard = 0;
  const capture = () => {
    SCI.days.push({ day, env: JSON.stringify(save(true)), coins, lifetime, rep, note: sciDayNote() });
  };
  sciBuy(plan);
  capture();
  while (day <= SCI.stopDay && !gameOver && !rule.hit() && guard++ < 400000) {
    const d0 = day;
    sciTick();
    if (tmin >= 9 * 60 && tmin <= 19 * 60) sciBuy(plan);
    if (day !== d0) capture();
  }
  if (!SCI.days.length || SCI.days[SCI.days.length - 1].day !== day) capture();
  // THE STREAM STAYS SEEDED for the rest of the lab session. Shuttling a
  // keyframe in mints its guests, and minting draws - hand the stream back to
  // the browser's own unseeded Math.random here and the same day would
  // materialize differently every time you scrubbed to it. Invisible in the
  // harness, whose Math.random is seeded anyway; a real bug in a real browser.
  SCI.run = false;
  SCI.at = SCI.days.length - 1;
  SCI.msg = gameOver ? "THE TOWN FAILED ON DAY " + day
    : won ? "THEY BOUGHT THE FERRY"
    : rule.hit() ? rule.name.replace("STOP AT ", "REACHED ").replace("STOP IF ", "")
    : "LIVED " + SCI.stopDay + " DAYS";
  // ...and the bench opens on the timeline it just lived. The run ticks with
  // screen = "play" because that is what simTown asks of the world; landing
  // there afterwards would drop the player into a town with no way back to
  // the days they came for.
  screen = "sci";
  sfx.ding();
}
// Materialize a day: the keyframe goes through the ordinary loader, so what
// you are looking at is a town this game could have loaded from a file.
function sciGoto(i) {
  const row = SCI.days[i];
  if (!row) return;
  SCI.run = true;                       // no slot writes while we shuttle
  sciShuttle(row.env);
  SCI.run = false;
  SCI.at = i;
  screen = "sci";
}
function sciPlay() {
  if (SCI.at < 0) return;
  const d = SCI.days[SCI.at].day;
  SCI.run = true; sciShuttle(SCI.days[SCI.at].env); SCI.run = false;
  screen = "play";
  SCI.days = []; SCI.at = -1;
  startMusic(); sfx.buy();
  toast = { text: "DAY " + d + " OF THAT TOWN IS YOURS NOW", t: 8 };
  slotOwned = true;                      // "YOURS NOW" is the deliberate act - the lab earns the slot only here
  save();                                // it becomes an ordinary town, in the ordinary slot
}
// ---- the bench itself. 5x7 for headings, 3x5 for the rows; every string that
// could run long goes through fitSmall, because the no-off-canvas sweep reads
// these screens too.
// the title's own entry, under the towns shelf and its count line
function sciTitleRect() { return { x: W / 2 - 50, y: (hasSave ? 138 : 122) + 46, w: 100, h: 16 }; }
const SCI_ROWS = [64, 80, 96, 112];      // seed / plan / span / rule
function sciRowRect(i) { return { x: 16, y: SCI_ROWS[i], w: W - 32, h: 14 }; }
function sciBarRect() { return { x: 16, y: H - 58, w: W - 32, h: 12 }; }
function sciBtnRect() { return { x: W / 2 - 50, y: H - 40, w: 100, h: 16 }; }
function sciBackRect() { return { x: 6, y: 6, w: 40, h: 12 }; }
function sciRunRect() { return { x: W / 2 - 50, y: 132, w: 100, h: 16 }; }
function sciFrame(dt) {
  window._viewCalls = (window._viewCalls || 0) + 1;
  const done = SCI.days.length > 0;
  if (done && SCI.at >= 0) { drawBG(); drawTown(); for (const c of crabs) drawCrab(c); drawNight(); }
  else { rect(ctx, 0, 0, W, H, [18, 14, 24]); }
  // a scrim so the bench is readable over a live town
  rect(ctx, 0, 0, W, done ? 30 : H, [18, 14, 24]);
  text(ctx, "CRAB SCIENCE", W / 2 - textWidth("CRAB SCIENCE") / 2, 10, [150, 220, 255]);
  {
    const r = sciBackRect();
    rect(ctx, r.x, r.y, r.w, r.h, [30, 20, 36]);
    smallText(ctx, "BACK", r.x + 4, r.y + 3, [200, 190, 180]);
  }
  if (!done) {
    smallText(ctx, "LIVE A TOWN OUT AND WALK ITS DAYS", 16, 40, [150, 140, 150]);
    const rows = [
      ["SEED", String(SCI.seed)],
      ["OPENING", SCI_PLANS[SCI.plan].name],
      ["SPAN", SCI.stopDay + " DAYS"],
      ["RULE", SCI_RULES[SCI.rule].name],
    ];
    rows.forEach(([k, v], i) => {
      const r = sciRowRect(i);
      rect(ctx, r.x, r.y, r.w, r.h, [30, 24, 40]);
      smallText(ctx, k, r.x + 4, r.y + 4, [150, 200, 230]);
      smallText(ctx, fitSmall(v, r.w - 76), r.x + 56, r.y + 4, [235, 225, 210]);
      smallText(ctx, "-", r.x + r.w - 20, r.y + 4, [200, 190, 180]);
      smallText(ctx, "+", r.x + r.w - 9, r.y + 4, [200, 190, 180]);
    });
    const b = sciRunRect();
    rect(ctx, b.x, b.y, b.w, b.h, [30, 20, 36]);
    rect(ctx, b.x + 1, b.y + 1, b.w - 2, b.h - 2, [90, 170, 120]);
    text(ctx, "LIVE IT", b.x + 32, b.y + 5, [20, 40, 28]);
    smallText(ctx, fitSmall("THE SAME RECIPE ALWAYS LIVES THE SAME TOWN", W - 32), 16, b.y + 24, [120, 112, 122]);
    return;
  }
  // ---- results + the timeline
  const at = SCI.drag >= 0 ? SCI.drag : SCI.at;
  const row = SCI.days[at] || SCI.days[SCI.days.length - 1];
  smallText(ctx, fitSmall(SCI.msg, W - 32), 16, 20, [235, 225, 210]);
  const bar = sciBarRect();
  rect(ctx, 0, bar.y - 16, W, H - bar.y + 16, [18, 14, 24]);
  smallText(ctx, fitSmall("DAY " + row.day + "  $" + $d(row.coins) + "  " + row.note, W - 32),
    16, bar.y - 12, [200, 220, 235]);
  rect(ctx, bar.x, bar.y, bar.w, bar.h, [30, 24, 40]);
  // one notch per lived day, the whole run at a glance
  const n = SCI.days.length;
  for (let i = 0; i < n; i++) {
    const x = bar.x + 1 + Math.floor(i * (bar.w - 2) / Math.max(1, n));
    const w = Math.max(1, Math.floor((bar.w - 2) / Math.max(1, n)) - 1);
    const d = SCI.days[i];
    const col = d.note === "THE TOWN FAILED" ? [200, 80, 80]
      : i === at ? [255, 216, 96] : [90, 130, 160];
    rect(ctx, x, bar.y + 1, w, bar.h - 2, col);
  }
  const b = sciBtnRect();
  rect(ctx, b.x, b.y, b.w, b.h, [30, 20, 36]);
  rect(ctx, b.x + 1, b.y + 1, b.w - 2, b.h - 2, [190, 140, 80]);
  text(ctx, "PLAY THIS DAY", b.x + 12, b.y + 5, [40, 24, 16]);
}
// ONE RULE, TWO INPUT DEVICES: every control here is a tap on a rect, and the
// scrub bar is a drag that COMMITS ON RELEASE - which is the same gesture a
// finger and a mouse both make, and it means one town is materialized per
// gesture instead of one per pixel.
function sciHit(p, r) { return p.x >= r.x && p.x < r.x + r.w && p.y >= r.y && p.y < r.y + r.h; }
function sciBarIndex(p) {
  const bar = sciBarRect(), n = SCI.days.length;
  if (!n) return -1;
  const i = Math.floor((p.x - bar.x) * n / Math.max(1, bar.w));
  return Math.max(0, Math.min(n - 1, i));
}
function sciTap(p) {
  if (sciHit(p, sciBackRect())) {
    if (SCI.days.length) { SCI.days = []; SCI.at = -1; SCI.msg = ""; sfx.ding(); return; }
    sciFreeStream(); screen = "title"; sfx.ding(); return;
  }
  if (!SCI.days.length) {
    const r0 = sciRowRect(0);
    for (let i = 0; i < 4; i++) {
      const r = sciRowRect(i);
      if (p.y < r.y || p.y >= r.y + r.h) continue;
      const minus = p.x >= r.x + r.w - 24 && p.x < r.x + r.w - 12;
      const plus = p.x >= r.x + r.w - 13;
      if (!minus && !plus) return;
      const d = plus ? 1 : -1;
      if (i === 0) SCI.seed = Math.max(1, SCI.seed + d);
      if (i === 1) SCI.plan = (SCI.plan + d + SCI_PLANS.length) % SCI_PLANS.length;
      if (i === 2) SCI.stopDay = Math.max(2, Math.min(30, SCI.stopDay + d));
      if (i === 3) SCI.rule = (SCI.rule + d + SCI_RULES.length) % SCI_RULES.length;
      sfx.ding();
      return;
    }
    // LIVE IT is a navigation, not a call: the recipe goes in the URL and the
    // town is built from nothing by the boot below. Same two-step shape as the
    // SEND chip - you set the recipe, then you commit it.
    if (sciHit(p, sciRunRect()))
      location.href = location.pathname + "?lab&seed=" + SCI.seed + "&plan=" + SCI.plan +
        "&span=" + SCI.stopDay + "&rule=" + SCI.rule;
    return;
  }
  if (sciHit(p, sciBtnRect())) { sciPlay(); return; }
  const i = sciBarIndex(p);
  if (i >= 0 && sciHit(p, sciBarRect())) { sciGoto(i); sfx.ding(); }
}

function frame(now) {
  refreshHatches();   // hatch flags snapshot: one global read set per frame
  // TWO CLOCKS, and the second one is new. `dt` is SIM time, scaled by the
  // speed chips, and everything in the world runs on it. `raw` is WALL time,
  // and the HIRE CARD runs on that instead: a card you are meant to read must
  // not get six times shorter because the town is running at 6x. It buys the
  // player nothing - the day underneath it is running at whatever speed they
  // chose - it just means the card is legible at every one of them. (The toast
  // deliberately stays on sim time: it is an event notice, and it belongs to
  // the moment in the day that produced it.)
  //
  // Deliberately computed BESIDE the dt line rather than out of it, so the
  // speed row's own arithmetic is left exactly as it was.
  //
  // AND `dt` NO LONGER ASKS ABOUT PAUSE. This branch was cut while a pause
  // still existed; the operator removed it (see the ruling at FF_SPEED) and a
  // union of the two sides here would have restored `paused ? 0 :` against a
  // name that no longer exists - a ReferenceError on the first frame, and the
  // whole game dark. Neither side was wrong; they were written a ruling apart.
  // THE QUANTIZER. Wall milliseconds in, WHOLE TICKS out, with the remainder
  // carried in an accumulator so a 60Hz browser (16.7ms - a third of a tick)
  // still advances the world instead of freezing at floor(0.33) = 0. Headless
  // steps exactly 50ms, so rawTicks is exactly 1 and msAcc never leaves 0 -
  // the sim's arithmetic is integer whether or not the clock feeding it is.
  const rawMs = Math.max(0, Math.min(100, now - last));
  msAcc += rawMs;
  const rawTicks = (msAcc - msAcc % 50) / 50;
  msAcc -= rawTicks * 50;
  dtT = rawTicks * TURBO * (ffSleep ? 6 : FF_SPEED[ffMode]);   // ticks this frame
  vpCamDt = (rawMs / 1000) * TURBO * (ffSleep ? 6 : FF_SPEED[ffMode]);   // same scaling, no quantizer
  const dt = dtT / TICK_HZ;   // seconds, for the view-side timers that still read them
  // the interpolation's prev image: the state the LAST render stood on,
  // taken only when this frame actually advances the world
  if (!window._headless && rawTicks > 0) { VP_PX.set(PXQ); VP_PY.set(PYQ); VP_WY.set(PWYQ); vpTicks = dtT; }
  last = now; T += dtT;
  simClock(dt, rawMs);
  if (screen === "intro") { introFrame(); requestAnimationFrame(frame); return; }
  if (screen === "title") { titleFrame(dt); requestAnimationFrame(frame); return; }
  // the bench is a READER like every other screen: it draws the town its
  // keyframe loaded and advances nothing - a run advances the sim inside
  // sciStart, synchronously, and is over before a frame is drawn
  if (screen === "sci") { sciFrame(dt); requestAnimationFrame(frame); return; }
  simTown(dt);
  if (window._headless) { requestAnimationFrame(frame); return; }   // sim-only mode: the seam
  vpSwapIn();
  viewFrame(dt);
  vpSwapOut();
  // sun mode: chain extra 0.6s sim steps synchronously (same per-step bound the
  // suite verifies at 6x) so the night passes in about a second of real time.
  // A LOOP, not a re-entrant frame() - the re-entrant form scheduled a rAF per
  // nested call, and every sun-skip left a permanent pack of parallel frame
  // loops behind it (the play-test's "slow and choppy after the sun"). The
  // steps are SIM-ONLY: same accumulator arithmetic, same tick math, and the
  // seam's own theorem is what makes skipping the six invisible draws legal -
  // a render moves nothing. It runs AFTER vpSwapOut, on the real planes.
  for (let c = 0; c < 6 && ffSleep && screen === "play" && !gameOver; c++) {
    msAcc += 100;
    const ct = (msAcc - msAcc % 50) / 50;
    msAcc -= ct * 50;
    dtT = ct * TURBO * 6;
    const cdt = dtT / TICK_HZ;
    T += dtT;
    simClock(cdt, 100);
    if (screen === "play") simTown(cdt);
    last = performance.now();   // chained steps ran ahead of the real clock
  }
  requestAnimationFrame(frame);
}

document.addEventListener("visibilitychange", () => { if (document.hidden) save(); else last = performance.now(); });
addEventListener("beforeunload", save);

initNpcs();
if (!FRESH) migrateLegacy();   // the old single-key town becomes slot 1, intact
activeSlot = readActiveSlot();
// The world has peoples in it before anybody saves one. load() installs them
// again alongside a save's own documents; a town with no save at all would
// otherwise sail forever with an empty mainland.
loadCultures(null);
// ...and a LAB town never reads a slot: its tick zero is this boot, not
// whatever the player last left behind. (The peoples above still arrive -
// pigs sail to a science town like any other.)
hasSave = LAB ? false : load();
// An EMPTY active slot is earned at boot: a first town must still autosave.
// A slot that HOLDS an envelope the loader refused stays unearned - the day-1
// town about to be built below must not bury a save somebody might fix.
if (!LAB && !hasSave) {
  let raw = null;
  try { raw = localStorage.getItem(slotKey(activeSlot)); } catch (e) {}
  if (raw == null) slotOwned = true;
}
if (!hasSave) {
  crabs = [newCrab(makeCrabPersona(0)), newCrab(makeCrabPersona(1))]; rosterGen++;
  coins = 15000;   // cents - a few bux in your pocket - rent is due tonight: ingredients + first rent buffer
  dayOpen = coins;   // day one opens on the float, so TODAY starts at +$0
}
// A NEW TOWN OPENS EMPTY and waits for the 08:00 boat; a SAVED town keeps
// exactly the guests it was saved with, and nothing is seeded on top of them.
// The one exception is a save written before the ferry existed, which has no
// guest list to restore - see seedVisitors(). Deliberately NOT inside load():
// a modern save that legitimately holds no visitors (saved at midnight, say)
// must stay empty rather than have a crowd conjured onto its promenade.
if (hasSave && preVisSave) seedVisitors();
// THE LAB RUNS ITS RECIPE HERE, on a world one line old. If the URL carries a
// seed the town is lived out immediately and the bench opens on its timeline;
// a bare `?lab` opens the setup form instead.
if (LAB) {
  screen = "sci";
  if (/[?&]seed=/.test(location.search)) {
    SCI.seed = LAB_ARG("seed", 1337);
    SCI.plan = Math.max(0, Math.min(SCI_PLANS.length - 1, LAB_ARG("plan", 0)));
    SCI.stopDay = Math.max(2, Math.min(30, LAB_ARG("span", 12)));
    SCI.rule = Math.max(0, Math.min(SCI_RULES.length - 1, LAB_ARG("rule", 0)));
    sciStart();
  }
}
requestAnimationFrame(frame);

// console cheat for tinkering: cheat(500)
window.cheat = (n) => { coins += n || 100; };
